    if not args.parent.is_dir() or not args.node_modules.is_dir():
        raise ValueError("Select the actual writable receiving parent and installed module directory")
    root = Path(tempfile.mkdtemp(prefix="scf-current-81cf-", dir=args.parent))
    source = root / "source"
    runtime = root / "runtime"
    output = root / "receiving"
    private = root / "private"
    temporary = root / "tmp"
    for path in (source, runtime, output, private, temporary):
        path.mkdir(mode=0o700)
    preserve_console(output / "producer-console.log")
    source_manifest = stage_rows(packet["files"], source, True)
    runtime_manifest = stage_rows(packet["runtime"], runtime, False)
    preceding_runtime = retain_runtime_edition(runtime, root)
    # Keep the executed producer and shared controller in the saved runtime,
    # including when a maintained producer receives an older complete packet.
    for name in ("receive_current.py", "scf_native_process.py"):
        actual_source = Path(__file__).with_name(name).read_bytes()
        (runtime / name).write_bytes(actual_source)
        (runtime / name).chmod(0o600)
    actual_runtime = record_runtime_selection(runtime, root, preceding_runtime)
    json_file(root / "source-selection.json", {
        "operationId": OPERATION, "sourceRepository": packet["sourceRepository"],
        "sourceCommit": packet["sourceCommit"], "reviewCommit": packet["reviewCommit"],
        "overlayBlob": packet["overlayBlob"], "files": source_manifest,
        "runtime": runtime_manifest, "packetSha256": args.expected_packet_sha256})
    (root / "complete-source-packet.json").write_bytes(packet_bytes)
    config = {
        "sourceRoot": str(source), "outputDirectory": str(output),
        "temporaryDirectory": str(temporary), "nodeModules": str(args.node_modules),
        "chromium": str(args.chromium), "sourceCommit": packet["sourceCommit"],
        "overlayBlob": packet["overlayBlob"], "port": 0, "files": source_manifest,
        "reviewDecisions": packet["reviewDecisions"],
        "reviewResolutions": packet["reviewResolutions"],
        "originalReviewPath": packet["originalReviewPath"],
        "originalReviewActions": packet["originalReviewActions"],
        "originalDraftExportSHA256": packet["originalDraftExportSHA256"],
    }
    json_file(root / "config.json", config)
    environment = dict(os.environ)
    environment.update({"TMPDIR": str(temporary), "TEMP": str(temporary), "TMP": str(temporary),
                        "PYTHONDONTWRITEBYTECODE": "1"})
    print("SCF_NATIVE_START " + json.dumps({
        "operationId": OPERATION, "root": str(root), "sourceFiles": len(source_manifest),
        "sourceCommit": packet["sourceCommit"], "originalReview": packet["originalReviewId"],
        "nativeRecord": str(output / "native-process.json"),
    }), flush=True)
    native_summary, result = run_receiving_program(
        OPERATION, root, output,
        {"source_commit": packet["sourceCommit"], "packet_sha256": args.expected_packet_sha256,
         "original_review_id": packet["originalReviewId"], "runtime_selection": actual_runtime,
         "library_replacement": {
             "library_file_id": args.replace_library_file_id,
             "expected_version": args.expected_library_version,
         }},
        args.node, args.chromium, runtime / "receive-current.cjs", root / "config.json",
        root, environment, args.timeout_seconds, "current-application",
    )
    state = native_summary["state"]
    native_summary.update(sourceCommit=packet["sourceCommit"], outputDirectory=str(output))
    json_file(output / "native-runtime.json", {
        "node": str(args.node), "nodeVersion": native_summary["nodeVersion"],
        "chromium": str(args.chromium), "browserVersion": native_summary["browserVersion"],
        "nodeModules": str(args.node_modules), "python": sys.version,
        "startedAt": native_summary["started_utc"], "operationId": OPERATION,
        "sourceFiles": len(source_manifest),
        "sourceBytes": sum(row["bytes"] for row in source_manifest),
        "sourceCommit": packet["sourceCommit"], "root": str(root),
        "nativeRecord": str(output / "native-process.json"),
    })
    if result:
        native_summary.update({key: result[key] for key in
                               ("originalDraftId", "originalReviewId", "reviewActions", "retainedOriginalActions")
                               if key in result})
    json_file(root / "native-result.json", native_summary)
    archive = root / ("SCF-Current-Application-and-Review" + ("" if state == "COMPLETE" else "-Partial") + ".zip")
    with zipfile.ZipFile(archive, "x", compression=zipfile.ZIP_DEFLATED, compresslevel=6) as bundle:
        for directory in (source, runtime, output, root / "runtime-editions"):
            for file in sorted(directory.rglob("*")):
                if file.is_symlink():
                    raise ValueError("Receiving output must retain ordinary files: " + str(file))
                if file.is_file():
                    # Browser captures remain available for internal inspection.
                    if file.is_relative_to(output) and file.suffix.lower() == ".png":
                        continue
                    bundle.write(file, file.relative_to(root).as_posix())
        for file in (root / "source-selection.json", root / "complete-source-packet.json",
                     root / "config.json", root / "native-result.json", root / "runtime-selection.json"):
            bundle.write(file, file.relative_to(root).as_posix())
    archive_meta = {"path": str(archive), "bytes": archive.stat().st_size,
                    "sha256": digest(archive.read_bytes())}
    json_file(root / "archive.json", archive_meta)
    print("SCF_NATIVE_RESULT " + json.dumps({**native_summary, "archive": archive_meta}), flush=True)
    replacement = ((args.replace_library_file_id, args.expected_library_version)
                   if args.replace_library_file_id else None)
    try:
        saved = save_outputs(runtime, [archive], private, replacement)
        if not saved["all_saved"] and state == "COMPLETE":
            return 2
    except Exception as error:
        json_file(private / "save-error.json", {"type": type(error).__name__, "message": str(error)})
        print("SCF_LIBRARY_SAVE_ERROR " + json.dumps({"type": type(error).__name__,
              "localArchive": str(archive), "privateDetail": str(private / "save-error.json")}), flush=True)
        if state == "COMPLETE":
            return 2
    if state != "COMPLETE":
        incomplete = output / "INCOMPLETE.json"
        if incomplete.exists():
            print("SCF_NATIVE_FAILURE " + incomplete.read_text(), flush=True)
        else:
            print("SCF_NATIVE_FAILURE " + json.dumps({"logTail":
                  next((Path(row["stdout"]).read_text(errors="replace")[-8000:]
                        for row in reversed(list(native_summary["phases"].values()))
                        if Path(row["stdout"]).is_file()), "")}), flush=True)
        return 1
    return 0

if __name__ == "__main__":
    raise SystemExit(main())

// MIT. Continue the current source case through its existing browser and writers.
// The equipped owner supplies its running source-selected page and keeps the
// original process, archive and guarded same-case save.
import { readFile, writeFile, mkdir, open, link, unlink } from 'node:fs/promises';
import { resolve, dirname, join, relative, isAbsolute } from 'node:path';
import { pathToFileURL } from 'node:url';
import { createHash, randomUUID } from 'node:crypto';

const OPERATION='SCF-GRANT-CURRENT-REVIEW-81CF-20261012';
const sha=value=>createHash('sha256').update(value).digest('hex');
const same=(left,right)=>JSON.stringify(left)===JSON.stringify(right);
const json=value=>JSON.stringify(value,null,2)+'\n';
const need=(value,message)=>{if(!value)throw new Error(message);};


async function retainedJSON(path){
  try{return JSON.parse(await readFile(path,'utf8'));}
  catch(error){if(error.code==='ENOENT')return null;throw error;}
}

// A complete receipt becomes visible in one link operation. An interrupted
// partial temporary file is never interpreted as an issued or accepted save.
async function retainJSON(path,value){
  const body=json(value),temporary=path+'.'+randomUUID()+'.tmp';
  const existing=await retainedJSON(path);
  if(existing!==null){need(same(existing,value),'Keep the different retained receipt: '+path);return existing;}
  let handle;
  try{
    handle=await open(temporary,'wx',0o600);await handle.writeFile(body);await handle.sync();
    await handle.close();handle=null;
    try{await link(temporary,path);}
    catch(error){if(error.code!=='EEXIST')throw error;
      need(same(await retainedJSON(path),value),'Keep the different retained receipt: '+path);}
    const directory=await open(dirname(path),'r');
    try{await directory.sync();}finally{await directory.close();}
    return value;
  }finally{
    if(handle)await handle.close().catch(()=>{});
    await unlink(temporary).catch(error=>{if(error.code!=='ENOENT')throw error;});
  }
}

// Reconcile the effect of the original CAS writer, never another draft version.
// The actual selected model supplies retainVersion; its saved timestamp comes
// from the observed native record rather than a new time or fabricated request.
function workingSaveDisposition(intent,candidate,retainVersion){
  const before=intent.before;
  need(candidate&&candidate.id===before.id,'Reconnect to the original browser save record.');
  if(same(candidate,before))return 'pending';
  need(candidate.revision===before.revision+1&&
    Array.isArray(candidate.input?.versions)&&
    candidate.input.versions.length===before.input.versions.length+1,
    'The original browser record has later or different work. Preserve it before continuing this save.');
  const version=candidate.input.versions.at(-1);
  need(typeof version.savedAt==='string'&&Number.isFinite(Date.parse(version.savedAt))&&
    typeof candidate.updatedAt==='string'&&Number.isFinite(Date.parse(candidate.updatedAt)),
    'Keep the actual original saved-version and native record timestamps.');
  const input=retainVersion(before.input,'Saved submission version',version.savedAt);
  const expected={id:before.id,revision:before.revision+1,
    name:input.folder||'Untitled merchant',
    resources:Array.isArray(input.resources)?input.resources.length:0,
    updatedAt:candidate.updatedAt,input};
  need(same(candidate,expected),
    'The next browser revision differs from the original working save. Preserve every later edit.');
  return 'complete';
}

export async function receiveCurrentSourceBrowser(page,{
  inputPath,outputDirectory,expectedOrigin
}={}){
  const actualInputPath=resolve(inputPath);
  const selectedInput=JSON.parse(await readFile(actualInputPath,'utf8'));
  const input={...selectedInput};
  need(input.schema==='stellar-forge.source-package-browser-receiving-input.v1'&&
    input.operationId===OPERATION,'Continue the original current-source browser input.');
  const inputRelative=input.caseRelativeInput||'receiving/source-package-continuation/browser-receiving-input.json';
  need(typeof inputRelative==='string'&&!isAbsolute(inputRelative)&&
    !inputRelative.includes('\\')&&inputRelative.split('/').every(part=>part&&part!=='.'&&part!=='..')&&
    inputRelative.endsWith('/browser-receiving-input.json'),
    'Retain the exact source phase input location inside this same case.');
  const inputParts=inputRelative.split('/');
  const caseUp=Array(inputParts.length-1).fill('..');
  const selectedCase=resolve(dirname(input.currentDraftPath),...caseUp);
  const currentCase=resolve(dirname(actualInputPath),...caseUp);
  need(relative(currentCase,actualInputPath)===inputRelative&&
    relative(selectedCase,input.currentDraftPath)===inputParts.slice(0,-1).join('/')+'/draft.json',
    'Open the actual retained source-phase input and complete draft location.');
  // Archive reopening changes locations while retaining the same source and case.
  for(const key of ['sourceRoot','currentDraftPath','currentReviewPath','sourcePackagePath',
    'originalRecordPath','originalDraftPath','originalReviewPath']){
    need(typeof input[key]==='string'&&isAbsolute(input[key]),
      'Retain the original absolute case location for '+key+'.');
    const within=relative(selectedCase,input[key]);
    need(within&&!isAbsolute(within)&&within!=='..'&&!within.startsWith('../'),
      'Select '+key+' within the original retained case.');
    input[key]=resolve(currentCase,within);
  }
  const origin=new URL(expectedOrigin).origin;
  need(/^https:\/\//.test(origin)||/^http:\/\/(127\.0\.0\.1|localhost|\[::1\])(?::\d+)?$/.test(origin),
    'Use the existing secure or loopback source-selected reader.');
  const output=resolve(outputDirectory||join(dirname(actualInputPath),'browser'));
  await mkdir(output,{recursive:true,mode:0o700});
  const stages=[],files=[],pageErrors=[];
  let independent=null,releaseRead=null,readRoute=null;
  const applicationURL=new URL('/grant-data/application.md',origin).href;
  const write=async(name,body)=>{
    const path=join(output,name);await mkdir(dirname(path),{recursive:true,mode:0o700});
    await writeFile(path,body,{mode:0o600});
    const result={path:name,bytes:Buffer.byteLength(body),sha256:sha(body)};
    files.push(result);return result;
  };
  const stage=async(name,details={})=>{
    const entry={name,at:new Date().toISOString(),...details};stages.push(entry);
    await writeFile(join(output,'progress.json'),json({operationId:OPERATION,stages}),{mode:0o600});
    console.log('SCF_CURRENT_SOURCE_BROWSER '+name);
