  const onError=error=>pageErrors.push({stage:stages.at(-1)?.name||'START',message:error.message});
  page.on('pageerror',onError);
  const settle=async(p,kind='editor')=>{
    const root=kind==='review'?'#review-workspace':'#workspace-root';
