                assert native_reopen["independentNativeReceiving"]["originalActionsRetained"]==baseline["reviewEvents"]
                assert native_reopen["sourceRecords"]==payload["sourceRecords"]
                assert native_reopen["sourcePackageSha256"]==payload["sourcePackageSha256"]
                assert native_reopen["originalDraftId"]=="scf-technical-buyer-draft-7108-20261012"
                assert native_reopen["originalReviewId"]=="SCF-TECHNICAL-BUYER-REVIEW-7108-20261012"
                result_summary["completedSourceReceiving"]={key:native_reopen[key] for key in ("reviewActions","reviewStatus","retainedOriginalActions","currentApplication","sourceRecords","sourcePackageSha256","selectedBundle","preparedEdition","independentNativeReceiving")}
            result_summary["reopenedArchive"]={"path":str(final),"bytes":final.stat().st_size,"sha256":digest.hexdigest(),"originalMembersRetained":len(names),"completeMembers":len(complete_names),"unchangedSubmissionSha256":original_submission_sha}
    if library_result:result_summary["library"]=library_result
    if returncode==0 and native_result and native_result["state"]=="COMPLETE" and library_result and library_result["all_saved"]:result_summary["state"]="COMPLETE"
    elif returncode:result_summary["error"]="The original receiver returned exit "+str(returncode)
except BaseException as error:
    result_summary["error"]=str(error)
    (logs/"producer-error.log").write_text(traceback.format_exc(),encoding="utf-8")
    emit("ERROR",errorType=type(error).__name__,error=str(error),traceback=traceback.format_exc()[-6000:],tracebackPath=str(logs/"producer-error.log"))
finally:
    cleanup()
    result_summary["cgroupAfter"]=observation()
    (root/"receiving-summary.json").write_text(json.dumps(result_summary,ensure_ascii=False,indent=2)+"\n",encoding="utf-8")
    emit("FINAL",**result_summary)

raise SystemExit(0 if result_summary["state"]=="COMPLETE" else 1)

#!/usr/bin/env node
// MIT. Continue the saved SCF review with its complete current source package.
import fs from 'node:fs/promises';
import path from 'node:path';
import {createHash} from 'node:crypto';
import {pathToFileURL} from 'node:url';
import {receiveCurrentSource,reopenCurrentSource,receiveCurrentReview,reopenCurrentReview,applyPreparedCurrentReview} from './source-phase.mjs';

const sha=body=>createHash('sha256').update(body).digest('hex');
const same=(a,b)=>JSON.stringify(a)===JSON.stringify(b);
const need=(value,message)=>{if(!value)throw Error(message);};
const json=value=>JSON.stringify(value,null,2)+'\n';
const configPath=process.argv[2],verifyOnly=process.argv[3]==='--verify';
need(configPath&&process.argv.slice(3).every(value=>value==='--verify'),'Select the original source-phase configuration.');
const cfg=JSON.parse(await fs.readFile(configPath,'utf8'));
need(cfg.operationId==='SCF-GRANT-CURRENT-REVIEW-81CF-20261012','Continue the original receiving operation.');
need(cfg.phaseId==='SCF-SUBMISSION-SOURCE-PACKAGE-A8CE-20261012','Select the following complete source phase.');
const output=path.resolve(cfg.outputDirectory),sourceRoot=path.resolve(cfg.sourceRoot);
const site=path.join(sourceRoot,'stellar-forge/developer-site'),dist=path.join(site,'dist');
const stages=[];let stageName='START';
async function read(name){return fs.readFile(path.join(output,name),'utf8');}
async function optional(name){try{return await read(name);}catch(error){if(error.code!=='ENOENT')throw error;return null;}}
async function write(name,body){
  need(typeof name==='string'&&!path.isAbsolute(name)&&!name.split('/').includes('..'),'Retain an original output path.');
  const file=path.join(output,name);await fs.mkdir(path.dirname(file),{recursive:true,mode:0o700});
  const temporary=file+'.new';await fs.writeFile(temporary,body,{mode:0o600});await fs.rename(temporary,file);
  return {name,bytes:Buffer.byteLength(body),sha256:sha(body)};
}
async function stage(name,detail={}){
  stageName=name;const memory=process.memoryUsage();
  stages.push({name,at:new Date().toISOString(),rssBytes:memory.rss,heapUsedBytes:memory.heapUsed,...detail});
  await write('prepared-native-progress.json',json({operationId:cfg.operationId,phaseId:cfg.phaseId,stages}));
  console.log('SCF_SOURCE_RECEIVING_STAGE '+JSON.stringify(stages.at(-1)));
  if(global.gc)global.gc();
}
const submission=await import(pathToFileURL(path.join(dist,'grant-submission-core.mjs')));
const handover=await import(pathToFileURL(path.join(dist,'grant-handover-source.mjs')));
const review=await import(pathToFileURL(path.join(dist,'grant-review-round-core.mjs')));
const exporter=await import(pathToFileURL(path.join(site,'grant-export.mjs')));

async function inputs(){
  const [draftText,reviewText,recordText,sourcePackageText,browserRecordText]=await Promise.all([
    fs.readFile(cfg.originalDraftPath,'utf8'),fs.readFile(cfg.originalReviewPath,'utf8'),
    fs.readFile(cfg.originalRecordPath,'utf8'),fs.readFile(cfg.sourcePackagePath,'utf8'),
    fs.readFile(cfg.originalBrowserRecordPath||cfg.originalRecordPath,'utf8')
  ]);
  need(sha(sourcePackageText)===cfg.sourcePackageSha256,'Receive the exact selected complete source package.');
  const savedRecord=JSON.parse(recordText);
  const originalDraft=await handover.openDraftEnvelope(draftText);
  const originalBrowserRecord=JSON.parse(browserRecordText);
  need(originalBrowserRecord.id&&Number.isSafeInteger(originalBrowserRecord.revision)&&
    originalBrowserRecord.input?.id===originalDraft.id,
    'Retain the actual original browser binding separately from the native edition.');
  const {input,...originalBrowserBinding}=originalBrowserRecord;
  if(savedRecord.schema==='stellar-forge.source-package-native-submission-record.v1'){
    need(savedRecord.operationId===cfg.operationId&&same(savedRecord.input,originalDraft)&&
      same(savedRecord.originalBrowserBinding,originalBrowserBinding),
      'Continue the preceding full native draft and its original browser lineage.');
  }else{
    need(same(savedRecord,originalBrowserRecord)&&same(savedRecord.input,originalDraft),
      'Retain the actual original saved submission and browser binding.');
  }
  need(originalDraft.id===cfg.draftId,'Continue the original saved draft.');
  return {draftText,reviewText,savedRecord,originalDraft,sourcePackageText,originalBrowserRecord,originalBrowserBinding};
}

async function receive(){
  const selected=await inputs();
  const oldResult=JSON.parse(await fs.readFile(cfg.originalResultPath,'utf8'));
  need(oldResult.state==='COMPLETE'&&oldResult.reviewActions===cfg.previousReviewEvents&&
    oldResult.originalDraftId===cfg.draftId&&oldResult.originalReviewId===cfg.reviewId,
    'Continue the exact completed original native review.');
  const complete=await receiveCurrentSource({
    operationId:cfg.operationId,draftId:cfg.draftId,reviewId:cfg.reviewId,
    previousReviewEvents:cfg.previousReviewEvents,originalDraftText:selected.draftText,
    originalReviewText:selected.reviewText,sourcePackageText:selected.sourcePackageText,
    sourcePackageSha256:cfg.sourcePackageSha256,sourceRecords:cfg.sourceRecords,at:cfg.at,
    submission,handover,exporter,sha256:sha
  });
  const deliveries=[];
  const manifestText=complete.files.get('source-receiving-manifest.json');
  // Publish the phase manifest after every full prepared file is present.
  for(const [name,body] of complete.files)if(name!=='source-receiving-manifest.json')
    deliveries.push(await write(name,body));
  deliveries.push(await write('source-receiving-manifest.json',manifestText));
  await stage('complete-source-and-prepared-submission',{
    originalDraftId:cfg.draftId,sourceRecords:cfg.sourceRecords,
    currentSource:complete.manifest.currentSource,preparedEdition:complete.manifest.preparedEdition,
    preservedVersions:complete.comparison.preserved.savedVersions,
    retainedEditedAnswers:complete.comparison.preserved.editedAnswers
  });
  const draftText=complete.files.get('draft.json');
  complete.originalRound=null;complete.files.clear();if(global.gc)global.gc();
  const joined=await receiveCurrentReview({
    operationId:cfg.operationId,originalReviewText:selected.reviewText,
    originalDraft:selected.originalDraft,originalDraftText:selected.draftText,currentReviewText:await optional('Current_Review_Checkpoint.json'),
    draftText,sourcePackageSha256:cfg.sourcePackageSha256,
    previousReviewEvents:cfg.previousReviewEvents,at:cfg.at,actorId:cfg.actorId,
    review,sha256:sha,onCheckpoint:body=>write('Current_Review_Checkpoint.json',body)
  });
  if(cfg.preparedReviewPath){
    const preparedText=await fs.readFile(cfg.preparedReviewPath,'utf8');
    const authored=await applyPreparedCurrentReview({
      round:joined.round,preparedText,preparedSha256:cfg.preparedReviewSha256,
      sourcePackageText:selected.sourcePackageText,actorId:cfg.actorId,at:cfg.at,
      submission,handover,review,sha256:sha,
      onCheckpoint:body=>write('Current_Review_Checkpoint.json',body)
    });
    Object.assign(joined,authored);
    joined.receiving.currentReviewEvents=joined.round.events.length;
    joined.receiving.actionsAdded=joined.round.events.length-cfg.previousReviewEvents;
    joined.receiving.status=joined.view.status;joined.receiving.readiness=joined.view.readiness;
    joined.receiving.preparedReview=authored.preparedReview;
    deliveries.push(await write('current-authored-review-receiving.json',json(authored.preparedReview)));
    await stage('original-authored-current-review-received',{
      recordedDecisions:authored.preparedReview.decisions.length,
      recordedResolutions:authored.preparedReview.resolutions.length,
      pending:authored.preparedReview.pending.length,reviewStatus:joined.view.status
    });
  }
  deliveries.push(await write('downloads/Current_Complete_Submission.json',draftText));
  deliveries.push(await write('downloads/Current_Complete_Review.json',joined.exported));
  deliveries.push(await write('downloads/Current_Review_Report.md',joined.report));
  const reviewComparison={schema:'stellar-forge.source-package-review-comparison.v1',
    operationId:cfg.operationId,phaseId:cfg.phaseId,at:cfg.at,draftId:cfg.draftId,reviewId:cfg.reviewId,
    sourcePackageSha256:cfg.sourcePackageSha256,sourceRecords:cfg.sourceRecords,
    ...joined.receiving,targets:joined.comparison.rows};
  deliveries.push(await write('source-review-comparison.json',json(reviewComparison)));
  const originalBinding=selected.originalBrowserBinding;
  const record={schema:'stellar-forge.source-package-native-submission-record.v1',
    operationId:cfg.operationId,phaseId:cfg.phaseId,at:cfg.at,originalBrowserBinding:originalBinding,
    originalDraftSha256:sha(selected.draftText),input:complete.draft,
    currentSourcePackageSha256:cfg.sourcePackageSha256,selectedReviewEdition:joined.view.selectedEdition};
  deliveries.push(await write('native-submission-record.json',json(record)));
  const browserInput={schema:'stellar-forge.source-package-browser-receiving-input.v1',
    operationId:cfg.operationId,phaseId:cfg.phaseId,sourceRoot,
    caseRelativeInput:(cfg.receivingDirectory||'receiving/source-package-continuation')+'/browser-receiving-input.json',
    originalRecordPath:cfg.originalBrowserRecordPath||cfg.originalRecordPath,originalDraftPath:cfg.originalDraftPath,
    originalReviewPath:cfg.originalReviewPath,currentDraftPath:path.join(output,'draft.json'),
    currentReviewPath:path.join(output,'downloads/Current_Complete_Review.json'),
    sourcePackagePath:cfg.sourcePackagePath,sourcePackageSha256:cfg.sourcePackageSha256,
    sourceRecords:cfg.sourceRecords,originalBrowserBinding:originalBinding,
    routes:{application:'/grant.html',companion:'/grant-companion.html',
      editor:'/grant-submission.html',review:'/grant-review-round.html'},
    sourceRead:'Open the original saved draft while the initial source read is pending, receive the complete package through Source editions, save the same local record, and reopen the full current native draft and original review in another browser store.'};
  deliveries.push(await write('browser-receiving-input.json',json(browserInput)));
  await stage('original-review-current-edition-selected',{
    originalReviewId:cfg.reviewId,retainedOriginalActions:cfg.previousReviewEvents,
    reviewActions:joined.round.events.length,reviewStatus:joined.view.status,
    carriedDecisions:joined.receiving.carriedDecisions,reopenedDecisions:joined.receiving.reopenedDecisions
  });
  await write('RESULT.json',json({
    schema:'stellar-forge.current-source-package-receiving.v1',state:'SOURCE_RECEIVED',
    operationId:cfg.operationId,phaseId:cfg.phaseId,sourcePackageSha256:cfg.sourcePackageSha256,
    sourceRecords:cfg.sourceRecords,sourceSelection:cfg.sourceSelection,
    receivingDirectory:cfg.receivingDirectory||'receiving/source-package-continuation',
    precedingSourceDirectory:cfg.precedingSourceDirectory||null,
    originalDraftId:cfg.draftId,originalReviewId:cfg.reviewId,
    originalBrowserBinding:originalBinding,retainedOriginalActions:cfg.previousReviewEvents,
    reviewActions:joined.round.events.length,reviewStatus:joined.view.status,
    reviewReceiving:joined.receiving,currentApplication:complete.manifest.currentSource,
    selectedBundle:complete.manifest.selectedBundle,preparedEdition:complete.manifest.preparedEdition,
    nativeSourceManifest:'source-receiving-manifest.json',deliveries,stages,
    memory:process.memoryUsage(),maxResidentSetKiB:process.resourceUsage().maxRSS
  }));
}

async function verify(){
  const prepared=JSON.parse(await read('RESULT.json'));
  need(['SOURCE_RECEIVED','COMPLETE'].includes(prepared.state)&&prepared.operationId===cfg.operationId&&
    prepared.phaseId===cfg.phaseId&&prepared.sourcePackageSha256===cfg.sourcePackageSha256,
    'Open the complete output of this original source phase.');
  const selected=await inputs();
  const manifest=JSON.parse(await read('source-receiving-manifest.json'));
  const reopened=await reopenCurrentSource({
    manifest,readOutput:read,originalReviewText:selected.reviewText,
    originalDraftText:selected.draftText,handover,submission,sha256:sha
  });
  const nativeFiles=new Set(manifest.files.map(row=>row.path));
  for(const file of prepared.deliveries)if(!nativeFiles.has(file.name)){
    const body=await read(file.name);
    need(Buffer.byteLength(body)===file.bytes&&sha(body)===file.sha256,
      'Retain the complete source-phase delivery: '+file.name);
  }
  const currentReviewText=await read('downloads/Current_Complete_Review.json');
  const joined=await reopenCurrentReview({
    originalReviewText:selected.reviewText,currentReviewText,originalDraftText:selected.draftText,
    currentDraftText:reopened.exported,previousReviewEvents:cfg.previousReviewEvents,review,handover
  });
  const record=JSON.parse(await read('native-submission-record.json'));
  const originalBinding=selected.originalBrowserBinding;
  need(same(record.originalBrowserBinding,originalBinding)&&same(record.input,joined.draft),
    'Retain the original browser binding and the exact independently reopened current draft.');
  need(joined.round.events.length===prepared.reviewActions&&joined.view.status===prepared.reviewStatus,
    'The current review state changed between the original receiving phases.');
  const authored=prepared.reviewReceiving?.preparedReview;
  if(authored){
    const body=await fs.readFile(cfg.preparedReviewPath,'utf8');
    need(sha(body)===authored.preparedSha256&&authored.preparedSha256===cfg.preparedReviewSha256,
      'Retain the same full authored review input in the independent receiving phase.');
    for(const row of authored.decisions){
      const actual=joined.view.decisions.find(item=>item.id===row.id);
      need(actual&&same(actual.target,row.target)&&actual.bindingSha256===row.bindingSha256&&
        actual.decision===row.decision&&sha(actual.note)===row.noteSha256&&
        sha(JSON.stringify(actual.references))===row.referencesSha256,
        'Independently retain each complete current authored decision.');
    }
    for(const row of authored.resolutions){
      const change=joined.view.changes.find(item=>item.id===row.changeId);
      const actual=change?.resolutions.find(item=>item.id===row.id);
      need(change?.status==='resolved'&&actual&&sha(actual.note)===row.noteSha256,
        'Independently retain each original current request resolution.');
    }
  }
  const independentlyExported=await review.exportReviewRound(joined.round,{now:cfg.at});
  const independentlyPrepared=await handover.createDraftEnvelope(joined.draft,{exportedAt:cfg.at});
  need(same(JSON.parse(independentlyExported).round,joined.round)&&
    same(JSON.parse(independentlyPrepared).draft,joined.draft),
    'Retain every complete body through independent native re-export.');
  const exports=[
    await write('downloads/Independently_Received_Review.json',independentlyExported),
    await write('downloads/Independently_Received_Submission.json',independentlyPrepared)
  ];
  await stage('independent-current-source-submission-and-review',{
    sourceRecords:cfg.sourceRecords,originalDraftId:cfg.draftId,originalReviewId:cfg.reviewId,
    reviewActions:joined.round.events.length,originalActionsRetained:joined.originalEvents,
    currentApplication:joined.draft.currentSource,reviewStatus:joined.view.status
  });
  const complete={...prepared,state:'COMPLETE',completedAt:new Date().toISOString(),
    independentNativeReceiving:{processId:process.pid,originalActionsRetained:joined.originalEvents,
      originalDraftId:joined.draft.id,originalReviewId:joined.round.id,
      reviewActions:joined.round.events.length,reviewStatus:joined.view.status,
      submissionSHA256:sha(independentlyPrepared),reviewSHA256:sha(independentlyExported),
      selectedSource:joined.draft.currentSource,sourceRecords:cfg.sourceRecords,exports,
      maxResidentSetKiB:process.resourceUsage().maxRSS},
    stages:[...prepared.stages,...stages],maxResidentSetKiB:Math.max(
      prepared.maxResidentSetKiB||0,process.resourceUsage().maxRSS)};
  await write('RESULT.json',json(complete));
  console.log('SCF_CURRENT_SOURCE_COMPLETE '+JSON.stringify({
    output,originalDraftId:cfg.draftId,originalReviewId:cfg.reviewId,
    sourceRecords:cfg.sourceRecords,reviewActions:joined.round.events.length,
    reviewStatus:joined.view.status,downloads:prepared.deliveries.length+exports.length
  }));
}
try{if(verifyOnly)await verify();else await receive();}
catch(error){
  await write('SOURCE_RECEIVING_INCOMPLETE.json',json({
    operationId:cfg.operationId,phaseId:cfg.phaseId,stage:stageName,
    error:error.message,stack:error.stack,stages
  })).catch(()=>{});
  console.error('SCF_CURRENT_SOURCE_FAILED '+JSON.stringify({stage:stageName,message:error.message}));
  process.exitCode=1;
}

#!/usr/bin/env python3
"""Observe the existing SCF native process and preserve its complete continuation.

Both SCF producers use this controller in their own process. Each phase launches
one original command in an owned process group. The controller streams the full
log, records actual host/process identity and keeps a portable atomic journal.
"""
from __future__ import annotations

import argparse
import codecs
import copy
from datetime import datetime, timezone
import hashlib
import json
import os
from pathlib import Path
import shutil
import signal
import socket
import subprocess
import sys
import time
import uuid

SCHEMA = "stellar-forge.native-process.v1"


def utc_now():
    return datetime.now(timezone.utc).isoformat(timespec="milliseconds").replace("+00:00", "Z")



class ContinuationConsole:
    """Keep producer output writable when its original terminal disconnects."""
    def __init__(self, original, path):
        self.original = original
        self.fallback_path = Path(path)
        self.fallback = None
        self.encoding = getattr(original, "encoding", "utf-8")

    def write(self, value):
        if self.fallback is not None:
            return self.fallback.write(value)
        try:
            written = self.original.write(value)
            self.original.flush()
            return written
        except (BrokenPipeError, OSError):
            self.fallback_path.parent.mkdir(parents=True, exist_ok=True, mode=0o700)
            self.fallback = self.fallback_path.open("a", encoding="utf-8", buffering=1)
            self.fallback_path.chmod(0o600)
            return self.fallback.write(value)

    def flush(self):
        if self.fallback is not None:
            self.fallback.flush()
        else:
            try:
                self.original.flush()
            except (BrokenPipeError, OSError):
                pass

    def isatty(self):
        return self.fallback is None and self.original.isatty()

    def fileno(self):
        return (self.fallback or self.original).fileno()


def preserve_console(path):
    if not isinstance(sys.stdout, ContinuationConsole):
        sys.stdout = ContinuationConsole(sys.stdout, path)


def file_identity(path):
    digest = hashlib.sha256()
    size = 0
    with Path(path).open("rb") as source:
        for chunk in iter(lambda: source.read(1024 * 1024), b""):
            size += len(chunk)
            digest.update(chunk)
    return {"bytes": size, "sha256": digest.hexdigest()}


def write_json(path, value):
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True, mode=0o700)
    temporary = path.with_name(path.name + "." + uuid.uuid4().hex + ".new")
    try:
        with temporary.open("x", encoding="utf-8") as out:
            os.chmod(temporary, 0o600)
            json.dump(value, out, ensure_ascii=False, indent=2, allow_nan=False)
            out.write("\n")
            out.flush()
            os.fsync(out.fileno())
        temporary.replace(path)
    finally:
        if temporary.exists():
            temporary.unlink()


def process_identity(pid):
    result = {"pid": pid, "host_id": socket.gethostname()}
    try:
        result["boot_id"] = Path("/proc/sys/kernel/random/boot_id").read_text().strip()
        result["pid_namespace"] = os.readlink("/proc/%s/ns/pid" % pid)
        raw = Path("/proc/%s/stat" % pid).read_text()
        # The process name can itself contain spaces and closing parentheses.
        fields = raw[raw.rfind(")") + 2:].split()
        result["start_ticks"] = fields[19]
        result["process_state"] = fields[0]
        result["parent_pid"] = int(fields[1])
        result["process_group_id"] = int(fields[2])
        result["session_id"] = int(fields[3])
    except (OSError, IndexError):
        pass
    return result


def memory_observation(pid=None):
    result = {}
    for name in ("memory.events", "memory.current", "memory.max", "memory.peak"):
        try:
            result[name] = (Path("/sys/fs/cgroup") / name).read_text().strip()
        except OSError:
            pass
    if pid is not None:
        try:
            for row in Path("/proc/%s/status" % pid).read_text().splitlines():
                if row.startswith("VmRSS:"):
                    result["process_rss_kib"] = int(row.split()[1])
        except (OSError, ValueError):
            pass
    return result


def runtime_manifest(runtime):
    runtime = Path(runtime)
    rows = []
    for path in sorted(runtime.rglob("*")):
        if "__pycache__" in path.parts or path.suffix == ".pyc":
            continue
        if path.is_symlink():
            raise ValueError("Retain ordinary runtime files: " + str(path))
        if path.is_file():
            rows.append({"path": path.relative_to(runtime).as_posix(), **file_identity(path)})
    return rows


def retain_runtime_edition(runtime, case_root):
    """Keep the complete prior runtime once for each distinct source edition."""
    runtime, case_root = Path(runtime), Path(case_root)
    rows = runtime_manifest(runtime)
    encoded = json.dumps(rows, sort_keys=True, separators=(",", ":")).encode("utf-8")
    edition = hashlib.sha256(encoded).hexdigest()
    root = case_root / "runtime-editions" / edition
    if not root.exists():
        stage = root.with_name(edition + "." + uuid.uuid4().hex + ".new")
        stage.mkdir(parents=True, mode=0o700)
        try:
            for row in rows:
                target = stage / "files" / row["path"]
                target.parent.mkdir(parents=True, exist_ok=True, mode=0o700)
                shutil.copyfile(runtime / row["path"], target)
                target.chmod(0o600)
            write_json(stage / "manifest.json", {
                "schema": "stellar-forge.receiving-runtime-edition.v1",
                "edition": edition, "files": rows,
            })
            stage.rename(root)
        finally:
            if stage.exists():
                shutil.rmtree(stage)
    return {"edition": edition, "path": root.relative_to(case_root).as_posix(),
            "files": len(rows)}


def record_runtime_selection(runtime, case_root, previous_edition):
    rows = runtime_manifest(runtime)
    value = {"schema": "stellar-forge.receiving-runtime-selection.v1",
             "previous_edition": previous_edition, "files": rows}
    path = Path(case_root) / "runtime-selection.json"
    write_json(path, value)
    return {"path": str(path), **file_identity(path),
            "previous_edition": previous_edition}


class NativeProcessController:
    def __init__(self, operation_id, root, record_path, source_context, stream=True):
        if not isinstance(operation_id, str) or not operation_id:
            raise ValueError("Keep the complete original operation ID")
        self.root = Path(root).resolve()
        self.record_path = Path(record_path).resolve()
        self.stream = stream
        self.started = time.monotonic()
        self.record = {
            "schema": SCHEMA, "operation_id": operation_id,
            "native_root": str(self.root), "record": str(self.record_path),
            "host_id": socket.gethostname(), "bootstrap_pid": os.getpid(),
            "controller_identity": process_identity(os.getpid()),
            "started_utc": utc_now(), "state": "PREPARING",
            "source_commit": source_context.get("source_commit"),
            "source": copy.deepcopy(source_context), "phases": {},
            "memory_before": memory_observation(), "artifacts": [],
        }
        self._save()

    def _save(self):
        self.record["observed_at"] = utc_now()
        console = getattr(sys.stdout, "fallback_path", None)
        if console is not None and console.is_file():
            self.record["detached_console"] = str(console)
        write_json(self.record_path, self.record)

    def _emit(self, text):
        if not self.stream:
            return
        try:
            print(text, end="", flush=True)
        except (BrokenPipeError, OSError):
            # A detached terminal must not abandon an already accepted process.
            self.stream = False

    def _observe_owned_group(self, process, phase):
        """Retain original descendants, including separately detached browsers."""
        group = phase["process_group"]
        snapshot = {}
        try:
            for entry in Path("/proc").iterdir():
                if not entry.name.isdecimal():
                    continue
                member = process_identity(int(entry.name))
                if all(key in member for key in ("start_ticks", "parent_pid",
                        "process_group_id", "session_id", "boot_id", "pid_namespace")):
                    snapshot[member["pid"]] = member
        except OSError as exc:
            group["observation_error"] = str(exc)
            return None
        keys = ("pid", "host_id", "boot_id", "pid_namespace", "start_ticks")

        def same(current, prior):
            return all(key in current and key in prior and current[key] == prior[key]
                       for key in keys)

        expected = [phase["process_identity"]] + group["observed_members"]
        # The original driver records its exact browser identity immediately
        # after launchServer. Its owner must be this exact original phase PID,
        # namespace and start time, including when the driver has since exited.
        for row in phase.get("progress_processes", []):
            owner, child = row.get("owner", {}), row.get("process", {})
            if not isinstance(owner, dict) or not isinstance(child, dict):
                continue
            if (same(owner, phase["process_identity"]) and
                    child.get("parent_pid") == owner.get("pid") and
                    all(child.get(key) == owner.get(key)
                        for key in ("host_id", "boot_id", "pid_namespace"))):
                expected.append(child)
        owned = {
            pid: current for pid, current in snapshot.items()
            if any(same(current, prior) for prior in expected)
        }
        # Follow current parentage while it still exists. Afterwards the exact
        # retained child identities survive reparenting to the host's init.
        changed = True
        while changed:
            changed = False
            groups = {(row["process_group_id"], row["session_id"])
                      for row in owned.values()}
            for pid, member in snapshot.items():
                if pid in owned:
                    continue
                parent = owned.get(member["parent_pid"])
                descendant = (
                    parent is not None and
                    int(member["start_ticks"]) >= int(parent["start_ticks"]) and
                    all(member[key] == parent[key]
                        for key in ("host_id", "boot_id", "pid_namespace"))
                )
                same_group = (member["process_group_id"], member["session_id"]) in groups
                if descendant or same_group:
                    owned[pid] = member
                    changed = True
        # Never signal the controller's own group. A command's original session
        # and its observed detached children have separately owned groups.
        if any(row["process_group_id"] == os.getpgrp() for row in owned.values()):
            group["observation_error"] = "An observed child shares the controller process group"
            return None
        previous_groups = {(row.get("process_group_id"), row.get("session_id"))
                           for row in expected}
        unanchored = [
            row for pid, row in snapshot.items()
            if pid not in owned and
            (row["process_group_id"], row["session_id"]) in previous_groups
        ]
        group["observed_at"] = utc_now()
        group["current_members"] = list(owned.values())
        group["current_groups"] = sorted({
            (row["process_group_id"], row["session_id"]) for row in owned.values()
        })
        if unanchored:
            group["unanchored_members"] = unanchored
            group["observation_error"] = "A prior group has no retained original process identity"
            return None
        group.pop("unanchored_members", None)
        group.pop("observation_error", None)
        retained = {(row.get("pid"), row.get("start_ticks")): row
                    for row in group["observed_members"]}
        retained.update({(row["pid"], row["start_ticks"]): row for row in owned.values()})
        group["observed_members"] = list(retained.values())
        return [row for row in owned.values() if row.get("process_state") not in ("Z", "X")]

    def _stop_owned(self, process, phase):
        if "group_cleanup_complete" in phase:
            return phase["group_cleanup_complete"]
        # Observe the original leader before poll() can reap it. A reaped leader
        # does not mean its Chromium/other children have left the owned group.
        remaining = self._observe_owned_group(process, phase)
        if remaining == []:
            process.poll()
            if "termination" in phase:
                phase["termination"].update(state="owned_group_stopped", completed_at=utc_now())
            phase["group_cleanup_complete"] = True
            return True
        phase["group_cleanup_complete"] = False
        termination = phase.setdefault("termination", {"requested_at": utc_now()})

        def observe():
            members = self._observe_owned_group(process, phase)
            process.poll()
            return members

        def signal_and_wait(signum, label):
            current = observe()
            if current is None or not current:
                return current
            termination.update(signal=label, signaled_at=utc_now(),
                               signaled_members=copy.deepcopy(current))
            self._save()
            groups = sorted({row["process_group_id"] for row in current})
            termination["signaled_groups"] = groups
            for pgid in groups:
                try:
                    os.killpg(pgid, signum)
                except ProcessLookupError:
                    continue
                except OSError as exc:
                    termination["error"] = {"type": type(exc).__name__, "message": str(exc)}
                    return None
            deadline = time.monotonic() + 10
            while True:
                current = observe()
                if current is None or not current or time.monotonic() >= deadline:
                    return current
                time.sleep(0.1)

        if remaining is not None:
            remaining = signal_and_wait(signal.SIGTERM, "SIGTERM")
            if remaining:
                termination["forced_at"] = utc_now()
                remaining = signal_and_wait(signal.SIGKILL, "SIGKILL")
        complete = remaining == []
        termination.update(
            state="owned_group_stopped" if complete else "owned_group_exit_pending",
            observed_at=utc_now(),
            remaining_members=copy.deepcopy(remaining),
        )
        if complete:
            termination["completed_at"] = utc_now()
        phase["group_cleanup_complete"] = complete
        self._save()
        return complete

    def run(self, name, command, log_path, *, cwd, env, timeout_seconds, progress_path=None):
        if name in self.record["phases"]:
            raise ValueError("Keep each original command phase once: " + name)
        if not isinstance(command, (list, tuple)) or not command or any(
                not isinstance(part, str) or not part for part in command):
            raise ValueError("Supply the original command as a complete argument array")
        if timeout_seconds <= 0:
            raise ValueError("Use a positive native phase timeout")
        log_path = Path(log_path)
        log_path.parent.mkdir(parents=True, exist_ok=True, mode=0o700)
        phase = {
            "state": "STARTING", "command": list(command), "cwd": str(cwd),
            "started_utc": utc_now(), "stdout": str(log_path), "stderr": str(log_path),
            "timeout_seconds": timeout_seconds, "timed_out": False,
            "pid": None, "exit_code": None,
        }
        self.record["phases"][name] = phase
        self.record["state"] = "RUNNING"
        self.record["current_phase"] = name
        self._save()
        process, interrupted, failure = None, False, None
        began = time.monotonic()
        maximum_rss = None
        decoder = codecs.getincrementaldecoder("utf-8")(errors="replace")
        progress_signature = None
        if progress_path is not None:
            try:
                previous_progress = Path(progress_path).stat()
                progress_signature = (previous_progress.st_mtime_ns, previous_progress.st_size)
            except OSError:
                pass
        next_heartbeat = began + 10
        next_memory = began

        def drain(reader, complete=False):
            count = 0
            while complete or count < 4:
                chunk = reader.read(65536)
                if not chunk:
                    break
                self._emit(decoder.decode(chunk))
                count += 1

        def progress():
            nonlocal progress_signature
            if progress_path is None:
                return False
            try:
                selected = Path(progress_path)
                stat = selected.stat()
                signature = (stat.st_mtime_ns, stat.st_size)
                if signature == progress_signature:
                    return False
                value = json.loads(selected.read_text(encoding="utf-8"))
                if not isinstance(value, dict):
                    return False
                operations = [value[key] for key in ("operation", "operationId", "operation_id")
                              if value.get(key) is not None]
                if any(operation != self.record["operation_id"] for operation in operations):
                    phase["progress_issue"] = "The progress file names a different operation"
                    return False
                phase["progress"] = value
                process_rows = []
                for stage in value.get("stages", []):
                    if isinstance(stage, dict) and isinstance(stage.get("owned_processes"), list):
                        process_rows.extend(row for row in stage["owned_processes"]
                                            if isinstance(row, dict))
                phase["progress_processes"] = process_rows
                phase["progress_source"] = str(selected)
                progress_signature = signature
                return True
            except (OSError, UnicodeError, json.JSONDecodeError):
                # The browser may be between truncate and write. Its complete
                # next version is read without replacing the last good version.
                return False

        with log_path.open("xb") as log:
            log_path.chmod(0o600)
            try:
                process = subprocess.Popen(
                    list(command), cwd=cwd, env=env, stdin=subprocess.DEVNULL,
                    stdout=log, stderr=subprocess.STDOUT, start_new_session=True,
                )
                phase.update(state="RUNNING", pid=process.pid,
                             process_identity=process_identity(process.pid))
                phase["process_group"] = {
                    "pgid": process.pid, "session_id": process.pid,
                    "observed_members": [],
                }
                self._observe_owned_group(process, phase)
                self._save()
                self._emit("SCF_NATIVE_PROCESS " + json.dumps({
                    "operation_id": self.record["operation_id"], "phase": name,
                    "host_id": self.record["host_id"], "pid": process.pid,
                    "record": str(self.record_path),
                }) + "\n")
                with log_path.open("rb") as reader:
                    while True:
                        changed = progress()
                        self._observe_owned_group(process, phase)
                        if process.poll() is not None:
                            break
                        drain(reader)
                        now = time.monotonic()
                        if now >= next_memory:
                            sample = memory_observation(process.pid)
                            phase["memory"] = sample
                            if "process_rss_kib" in sample:
                                maximum_rss = max(maximum_rss or 0, sample["process_rss_kib"])
                            next_memory = now + 2
                        if changed or now >= next_heartbeat:
                            self._save()
                            next_heartbeat = now + 10
                        if now - began >= timeout_seconds:
                            phase["timed_out"] = True
                            progress()
                            self._stop_owned(process, phase)
                            break
                        time.sleep(0.4)
                    progress()
                    self._stop_owned(process, phase)
                    drain(reader, complete=phase.get("group_cleanup_complete", False))
                    progress()
                    self._emit(decoder.decode(b"", final=True))
            except KeyboardInterrupt:
                interrupted = True
            except Exception as exc:
                failure = {"type": type(exc).__name__, "message": str(exc)}
            finally:
                if process is not None and "process_group" in phase:
                    progress()
                    self._stop_owned(process, phase)
                if process is not None:
                    phase["exit_code"] = process.poll()
        if failure:
            phase["error"] = failure
        phase["interrupted"] = interrupted
        phase["completed_utc"] = utc_now()
        phase["duration_seconds"] = round(time.monotonic() - began, 3)
        phase["maximum_observed_rss_kib"] = maximum_rss
        if process is None or phase.get("group_cleanup_complete", False):
            phase["stdout_identity"] = file_identity(log_path)
        else:
            phase["stdout_identity"] = {
                "bytes_observed": log_path.stat().st_size, "observed_at": utc_now(),
                "writer_exit_pending": True,
            }
        phase["stderr_identity"] = phase["stdout_identity"]
        phase["state"] = (
            "INTERRUPTED" if interrupted else
            "TIMED_OUT" if phase["timed_out"] else
            "LAUNCH_FAILED" if process is None else
            "FAILED" if failure or phase["exit_code"] != 0 or
                not phase.get("group_cleanup_complete", False) else "COMPLETE"
        )
        self.record["state"] = "PHASE_COMPLETE" if phase["state"] == "COMPLETE" else "INCOMPLETE"
        self._save()
        return copy.deepcopy(phase)

    def finish(self, state, application_result=None, error=None):
        if state not in ("COMPLETE", "INCOMPLETE", "INTERRUPTED"):
            raise ValueError("Use the observed application completion state")
        self.record["state"] = state
        self.record["completed_utc"] = utc_now()
        self.record["duration_seconds"] = round(time.monotonic() - self.started, 3)
        self.record["memory_after"] = memory_observation()
        if application_result:
            self.record["application_result"] = {
                "path": str(application_result), **file_identity(application_result),
            }
        if error:
            self.record["error"] = copy.deepcopy(error)
        self._save()
        return copy.deepcopy(self.record)


def run_receiving_program(operation_id, root, output, source_context, node, chromium,
                          driver, config_path, cwd, env, timeout_seconds, phase_name,
                          engine="browser"):
    """Run the original browser or prepared-model programme with one controller."""
    if engine not in ("browser", "native"):
        raise ValueError("Select the original browser or native review engine")
    root, output = Path(root), Path(output)
    controller = NativeProcessController(
        operation_id, root, output / "native-process.json", source_context)
    controller.record["engine"] = engine
    commands = [
        ("javascript-parse", [str(node), "--check", str(driver)], 30, False),
        ("node-version", [str(node), "--version"], 30, False),
    ]
    execution_names = [phase_name]
    if engine == "browser":
        if chromium is None:
            raise ValueError("The original browser programme requires its selected Chromium")
        commands.append(("browser-version", [str(chromium), "--version"], 30, False))
        commands.append((phase_name, [str(node), str(driver), str(config_path)], timeout_seconds, True))
        progress_name = "progress.json"
    else:
        native_command = [
            str(node), "--max-old-space-size=256", "--expose-gc", str(driver), str(config_path),
        ]
        verification_name = "independent-native-receiving"
        execution_names.append(verification_name)
        commands.extend([
            (phase_name, native_command, timeout_seconds, True),
            (verification_name, native_command + ["--verify"], timeout_seconds, True),
        ])
        progress_name = "prepared-native-progress.json"
    deadline = None
    for name, command, timeout, execution in commands:
        if execution:
            if deadline is None:
                deadline = time.monotonic() + timeout_seconds
            timeout = deadline - time.monotonic()
            if timeout <= 0:
                phase = {
                    "state": "NOT_STARTED", "command": command, "pid": None,
                    "exit_code": None, "timed_out": True,
                    "reason": "The original receiving timeout elapsed before this phase",
                    "observed_at": utc_now(),
                }
                controller.record["phases"][name] = phase
                controller.record["current_phase"] = name
                controller._save()
                break
        log = output / ("native-process.log" if name == phase_name else name + ".log")
        phase = controller.run(
            name, command, log, cwd=cwd, env=env, timeout_seconds=timeout,
            progress_path=output / progress_name if execution else None)
        if phase["state"] != "COMPLETE":
            break
    result_path = output / "RESULT.json"
    result, result_error = None, None
    if phase_name in controller.record["phases"] and result_path.is_file():
        try:
            result = json.loads(result_path.read_text(encoding="utf-8"))
            if not isinstance(result, dict):
                raise ValueError("The original receiving result must be a JSON object")
            identifiers = [result[key] for key in ("operation", "operationId", "operation_id")
                           if result.get(key) is not None]
            if any(identifier != operation_id for identifier in identifiers):
                raise ValueError("The receiving result names a different original operation")
        except (OSError, ValueError, UnicodeError) as exc:
            result_error = {"type": type(exc).__name__, "message": str(exc)}
            result = None
    complete = (
        all(controller.record["phases"].get(name, {}).get("state") == "COMPLETE"
            for name in execution_names)
        and result is not None and result.get("state") == "COMPLETE"
    )
    state = "COMPLETE" if complete else "INCOMPLETE"
    native = controller.finish(
        state, application_result=result_path if result_path.is_file() else None,
        error=result_error)
    native["processExit"] = phase["exit_code"]
    native["timedOut"] = any(row.get("timed_out") for row in native["phases"].values())
    native["durationSeconds"] = native["duration_seconds"]
    observations = [native["phases"].get(name, {}).get("maximum_observed_rss_kib")
                    for name in execution_names]
    native["nodeMaxObservedRssKiB"] = max(
        (value for value in observations if value is not None), default=None)
    native["nodeVersion"] = (
        (output / "node-version.log").read_text(errors="replace").strip()
        if (output / "node-version.log").is_file() else None)
    native["browserVersion"] = (
        (output / "browser-version.log").read_text(errors="replace").strip()
        if engine == "browser" and (output / "browser-version.log").is_file() else None)
    return native, result


def inspect_record(path):
    """Read an existing record and observe only identities from this same host."""
    record = json.loads(Path(path).read_text(encoding="utf-8"))
    if record.get("schema") != SCHEMA:
        raise ValueError("Select an original SCF native process record")
    live = []
    for name, phase in record.get("phases", {}).items():
        expected = phase.get("process_identity")
        if not expected:
            continue
        current = process_identity(expected["pid"])
        keys = ("host_id", "boot_id", "pid_namespace", "start_ticks")
        if not all(key in expected for key in keys):
            state = "identity_unavailable"
        elif not all(key in current for key in keys):
            state = "not_observed_in_current_namespace"
        elif all(current[key] == expected[key] for key in keys):
            state = ("same_process_exited_zombie" if current.get("process_state") == "Z"
                     else "same_process_observed")
        else:
            state = "different_process_or_namespace"
        live.append({"phase": name, "identity_state": state,
                     "expected": expected, "observed": current})
    return {"record": record, "observed_at": utc_now(), "process_observations": live}


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--inspect", type=Path, required=True,
                        help="Read an existing native-process.json and its current process identity")
    args = parser.parse_args()
    print(json.dumps(inspect_record(args.inspect), ensure_ascii=False, indent=2))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

// Following source phase for the existing SCF current application and review.
// Runs inside the original receiving controller with its selected current modules.
export async function receiveCurrentSource({
  operationId, draftId, reviewId, previousReviewEvents, originalDraftText,
  originalReviewText, sourcePackageText, sourcePackageSha256, sourceRecords,
  at, submission, handover, exporter, sha256
}) {
  const need=(condition,message)=>{if(!condition)throw new Error(message);};
  const same=(a,b)=>JSON.stringify(a)===JSON.stringify(b);
  const clone=value=>JSON.parse(JSON.stringify(value));
  need(operationId==='SCF-GRANT-CURRENT-REVIEW-81CF-20261012','Continue the original SCF receiving operation.');
  need(typeof at==='string'&&Number.isFinite(Date.parse(at)),'Retain this receiving phase time.');
  need(await sha256(sourcePackageText)===sourcePackageSha256,'The selected complete source package has changed.');
  const originalExport=JSON.parse(originalDraftText.replace(/^\uFEFF/,''));
  const before=originalExport.schema===submission.ENVELOPE?
    await handover.openDraftEnvelope(originalDraftText):await handover.verifyHandover(originalExport);
  need(before.id===draftId,'The selected saved submission belongs to another draft.');
  const originalReview=JSON.parse(originalReviewText.replace(/^\uFEFF/,''));
  need(originalReview.schema==='stellar-forge.grant-review-round-export.v1'&&
    originalReview.round?.id===reviewId,'Retain the original complete review export.');
  const originalRound=originalReview.round;
  need(originalRound.events.length===previousReviewEvents,'Retain the selected completed review revision.');
  need(await sha256(JSON.stringify(originalRound))===originalReview.sha256,'The original review envelope differs from its complete body.');
  const incoming=await handover.openReviewerSourcePackage(sourcePackageText);
  const sourceIndexFile=incoming.bundle.body.files.find(row=>row.role==='source-index');
  need(sourceIndexFile,'Retain the complete source index.');
  const indexObject=incoming.objects.find(row=>row.sha256===sourceIndexFile.sha256);
  need(indexObject,'Retain the source index object.');
  const indexBytes=Buffer.from(indexObject.base64,'base64');
  const sourceIndex=JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(indexBytes));
  need(sourceIndex.sources.length===sourceRecords,'The complete reviewer source count differs from the selected edition.');
  need(incoming.bundle.body.files.length===4,'Receive all four original reviewer files.');
  const compared=submission.compareSource(before,incoming.source);
  const received=await handover.receiveReviewerSource(before,incoming,{at});
  need(received.id===before.id,'Retain the original draft identity.');
  need(received.currentSource===incoming.source.sha256,'Select the complete new application source.');
  const oldVersionCount=before.versions.length;
  need(same(received.versions.slice(0,oldVersionCount),before.versions),'Retain every original saved version.');
  for(const key of ['form','fields','reviews','planSources','planningReview','planningTargets','planningUpdate'])
    need(same(received[key],before[key]),'Source receiving changed the original '+key+'.');
  for(const source of before.sources)
    need(received.sources.some(value=>same(value,source)),'Retain every preceding application source.');
  const afterAnswers=new Map(received.answers.map(answer=>[answer.id,answer]));
  const comparisons=compared.map(change=>{
    const prior=before.answers.find(answer=>answer.id===change.id);
    const after=afterAnswers.get(change.id);
    need(after,'Retain every original answer identity.');
    if(change.edited)need(same(after,prior),'Preserve the complete edited answer and original source baseline: '+change.id);
    else {
      need(after.text===change.text&&after.baseText===change.text&&after.sourceSha===incoming.source.sha256,
        'Receive the complete unchanged answer from the selected source: '+change.id);
      need(after.note===prior.note,'Preserve the original answer note: '+change.id);
    }
    return {id:change.id,title:change.title,edited:change.edited,sourceChanged:change.sourceChanged,
      choice:change.edited?'retained-edited-answer':'received-current-source',
      prior:clone(prior),incomingText:change.text,received:clone(after)};
  });
  const oldHandover=before.handover;
  const newHandover=received.handover;
  if(oldHandover)for(const collection of ['objects','bundles','evidence','editions','returns'])
    for(const row of oldHandover[collection]||[])
      need((newHandover?.[collection]||[]).some(value=>same(value,row)),'Retain original handover '+collection+'.');
  need(newHandover?.selection.bundleId===incoming.bundle.id,'Select the received complete reviewer bundle.');
  const full=await exporter.prepareGrantExport(received,{selection:'auto',format:'plain',generatedAt:at});
  need(full.draft.id===draftId,'Keep the original draft in the prepared export.');
  need(same(full.draft.versions.slice(0,oldVersionCount),before.versions),'Retain all original versions in the prepared export.');
  const outputDraftText=full.files.get('draft.json');
  need(typeof outputDraftText==='string','Retain the complete prepared submission export.');
  const comparison={
    schema:'commons.scf-current-review-source-comparison.v1',operationId,at,draftId,reviewId,
    previousReviewEvents,originalReviewSha256:await sha256(originalReviewText),
    beforeSource:before.currentSource,currentSource:incoming.source.sha256,
    sourcePackageSha256,bundleId:incoming.bundle.id,sourceRecords,
    answers:comparisons,form:clone(received.form),fields:clone(received.fields),
    preserved:{savedVersions:oldVersionCount,originalSources:before.sources.length,
      editedAnswers:comparisons.filter(row=>row.edited).map(row=>row.id),
      priorReviewEvents:previousReviewEvents}
  };
  full.files.set('source-comparison.json',JSON.stringify(comparison,null,2)+'\n');
  const files=[];
  for(const [path,text] of full.files)files.push({path,bytes:Buffer.byteLength(text),sha256:await sha256(text)});
  const manifest={
    schema:'commons.scf-current-review-source-receiving.v1',operationId,at,
    draftId,reviewId,previousReviewEvents,sourcePackageSha256,
    selectedBundle:incoming.bundle.id,currentSource:incoming.source.sha256,
    sourceRecords,preparedEdition:full.edition.id,
    sourceFiles:incoming.bundle.body.files.map(row=>({...row})),
    input:{draftBytes:Buffer.byteLength(originalDraftText),draftSha256:await sha256(originalDraftText),
      reviewBytes:Buffer.byteLength(originalReviewText),reviewSha256:await sha256(originalReviewText)},
    files
  };
  full.files.set('source-receiving-manifest.json',JSON.stringify(manifest,null,2)+'\n');
  return {files:full.files,manifest,comparison,draft:full.draft,originalRound};
}

export async function reopenCurrentSource({
  manifest, readOutput, originalReviewText, originalDraftText,
  handover, submission, sha256
}) {
  const need=(condition,message)=>{if(!condition)throw new Error(message);};
  const same=(a,b)=>JSON.stringify(a)===JSON.stringify(b);
  need(await sha256(originalReviewText)===manifest.input.reviewSha256,'Retain the same completed original review input.');
  need(await sha256(originalDraftText)===manifest.input.draftSha256,'Retain the same completed original submission input.');
  for(const file of manifest.files) {
    const text=await readOutput(file.path);
    need(Buffer.byteLength(text)===file.bytes&&await sha256(text)===file.sha256,
      'The received complete output changed: '+file.path);
  }
  const exported=await readOutput('draft.json');
  const draft=await handover.openDraftEnvelope(exported);
  need(draft.id===manifest.draftId&&draft.currentSource===manifest.currentSource,
    'Reopen the selected current source in the original saved draft.');
  const original=JSON.parse(originalDraftText.replace(/^\uFEFF/,''));
  const before=original.schema===submission.ENVELOPE?
    await handover.openDraftEnvelope(originalDraftText):await handover.verifyHandover(original);
  need(same(draft.versions.slice(0,before.versions.length),before.versions),'Retain the original full version prefix.');
  const selected=await handover.reviewerSourceFromDraft(draft,manifest.selectedBundle);
  const source=await handover.openReviewerSourcePackage(await readOutput('source-package.json'));
  need(same(source,selected),'Independently reopened source files differ from the selected saved bundle.');
  for(const key of ['form','fields','reviews','planSources','planningReview','planningTargets','planningUpdate'])
    need(same(draft[key],before[key]),'Independent receiving changed the original '+key+'.');
  const nativeEdition=draft.handover.editions.find(row=>row.id===manifest.preparedEdition);
  need(nativeEdition,'Retain the selected native prepared output.');
  const text=await readOutput('prepared.txt');
  need(text===nativeEdition.body.output.text,'The complete output differs from its original prepared edition.');
  return {draft,exported,source,preparedEdition:nativeEdition.id};
}


// Use the original review lifecycle to select this complete current draft.
export async function receiveCurrentReview({
  operationId, originalReviewText, originalDraft, originalDraftText, currentReviewText, draftText,
  sourcePackageSha256, previousReviewEvents, at, actorId, review, sha256,
  onCheckpoint=async()=>{}
}) {
  const need=(condition,message)=>{if(!condition)throw new Error(message);};
  const same=(a,b)=>JSON.stringify(a)===JSON.stringify(b);
  need(operationId==='SCF-GRANT-CURRENT-REVIEW-81CF-20261012','Continue the original SCF review operation.');
  const baseline=await review.importReviewRound(originalReviewText);
  need(baseline.events.length===previousReviewEvents,'Retain the selected finished review revision.');
  const initial=await review.reviewRoundView(baseline);
  let workingBaseline=null;
  if(!same(initial.draft,originalDraft)){
    need(typeof originalDraftText==='string'&&initial.draft.id===originalDraft.id&&
      same(originalDraft.versions.slice(0,initial.draft.versions.length),initial.draft.versions)&&
      same(originalDraft.sources.slice(0,initial.draft.sources.length),initial.draft.sources),
      'Retain the reviewed draft history and sources in the current working submission.');
    const opened=await review.readSubmissionExport(originalDraftText,{
      fileName:'Original_Working_Submission.json',receivedAt:at});
    need(same(JSON.parse(opened.exportText).draft,originalDraft),
      'Open the complete actual working submission selected by this saved case.');
    workingBaseline=await review.compareReviewDraft(baseline,opened);
  }
  need(initial.participants.some(row=>row.id===actorId),'Use the original receiving participant selected for this continuation.');
  let round=currentReviewText?await review.importReviewRound(currentReviewText):baseline;
  const preserve=()=>{
    need(round.id===baseline.id&&same(round.events.slice(0,baseline.events.length),baseline.events),
      'Retain every completed original review action.');
    need(same(round.editions.slice(0,baseline.editions.length),baseline.editions),
      'Retain every original complete reviewed draft.');
  };
  preserve();
  let view=await review.reviewRoundView(round);
  const capture=await review.readSubmissionExport(draftText,{
    fileName:'Current_Complete_Submission.json',receivedAt:at});
  const originalReviewSha256=await sha256(originalReviewText);
  const requestId=async kind=>'SCF-SOURCE-A8CE-'+await sha256(JSON.stringify({
    operationId,sourcePackageSha256,originalReviewSha256,captureId:capture.id,kind}));
  const selectedBefore=initial.selectedEdition;
  const comparison=await review.compareReviewDraft(baseline,capture);
  const decisions=comparison.decisions.map(row=>({
    decisionId:row.decision.id,choice:row.canCarry?'carry':'reopen',
    note:row.canCarry?
      'The exact target text, source context, issuer prompt and limits remain unchanged in the complete received edition.':
      'The complete source receiving changes this target or its source context. The prior source-specific judgment remains in the original history; review the selected current target.'
  }));
  if(view.selectedEdition!==capture.id) {
    const allowed=new Set([await requestId('reopen'),await requestId('receive')]);
    need(round.events.slice(baseline.events.length).every(event=>allowed.has(event.id)),
      'The saved review advanced beyond this receiving phase. Continue its latest selected draft before changing this source selection.');
    if(view.status==='COMPLETE') {
      const id=await requestId('reopen');
      round=await review.applyReviewAction(round,{
        requestId:id,expectedRevision:round.events.length,actorId,kind:'reopen',at,
        input:{note:'Receive the complete current source package and prepared original submission. Retain the finished '+previousReviewEvents+'-action review and its previous source-specific judgments.'}
      });
      preserve();await onCheckpoint(await review.exportReviewRound(round,{now:at}));
      view=await review.reviewRoundView(round);
    }
    const id=await requestId('receive');
    round=await review.applyReviewAction(round,{
      requestId:id,expectedRevision:round.events.length,actorId,kind:'receive',at,
      input:{editionId:capture.id,fromEdition:view.selectedEdition,
        note:'Receive the complete source package, original authored answers and notes, saved field and plan bindings, and the native prepared submission. Source receiving was composed by A8CE for the original equipped reviewer.',
        decisions}
    },capture);
    preserve();await onCheckpoint(await review.exportReviewRound(round,{now:at}));
    view=await review.reviewRoundView(round);
  }
  need(view.selectedEdition===capture.id&&same(view.draft,JSON.parse(draftText).draft),
    'The current review must select the same complete prepared submission.');
  const exported=await review.exportReviewRound(round,{now:at});
  const report=await review.reviewReport(round);
  return {round,exported,report,view,comparison,
    receiving:{originalReviewSha256,originalReviewEvents:baseline.events.length,
      currentReviewEvents:round.events.length,originalEditions:baseline.editions.length,
      selectedBefore,selectedEdition:capture.id,status:view.status,
      carriedDecisions:decisions.filter(row=>row.choice==='carry').length,
      reopenedDecisions:decisions.filter(row=>row.choice==='reopen').length,
      actionsAdded:round.events.length-baseline.events.length,
      readiness:view.readiness,choices:decisions,
      workingBaseline:workingBaseline?{reviewedEdition:initial.selectedEdition,
        rows:workingBaseline.rows}:null}};
}

export async function reopenCurrentReview({
  originalReviewText, currentReviewText, originalDraftText, currentDraftText,
  previousReviewEvents, review, handover
}) {
  const need=(condition,message)=>{if(!condition)throw new Error(message);};
  const same=(a,b)=>JSON.stringify(a)===JSON.stringify(b);
  let baseline=await review.importReviewRound(originalReviewText);
  need(baseline.events.length===previousReviewEvents,'Retain the complete original review input.');
  const history={id:baseline.id,events:baseline.events,editions:baseline.editions};
  baseline=null;if(global.gc)global.gc();
  const round=await review.importReviewRound(currentReviewText);
  need(round.id===history.id&&same(round.events.slice(0,history.events.length),history.events)&&
    same(round.editions.slice(0,history.editions.length),history.editions),
    'Independent receiving changed the original review or its complete draft history.');
  const view=await review.reviewRoundView(round);
  const currentDraft=await handover.openDraftEnvelope(currentDraftText);
  const originalDraft=await handover.openDraftEnvelope(originalDraftText);
  need(currentDraft.id===originalDraft.id&&same(view.draft,currentDraft),
    'Independently open the same original prepared submission and selected review edition.');
  return {round,view,draft:currentDraft,originalEvents:history.events.length};
}


// Receive the original authors' following complete review against its exact source.
export async function applyPreparedCurrentReview({
  round, preparedText, preparedSha256, sourcePackageText, actorId, at,
  submission, handover, review, sha256, onCheckpoint=async()=>{}
}) {
  const need=(condition,message)=>{if(!condition)throw new Error(message);};
  const same=(a,b)=>JSON.stringify(a)===JSON.stringify(b);
  need(await sha256(preparedText)===preparedSha256,'Retain the complete selected prepared review.');
  const prepared=JSON.parse(preparedText);
  need(prepared.schema==='scf.current-application-review.v1'&&prepared.review_id===round.id&&
    prepared.operation==='SCF-GRANT-CURRENT-REVIEW-81CF-20261012',
    'Select the original authors’ current complete review.');
  const source=await handover.openReviewerSourcePackage(sourcePackageText);
  const roles={application:'application',companion:'product-and-finance',index:'source-index'};
  for(const [name,role] of Object.entries(roles)){
    const selected=prepared.selection[name],file=source.bundle.body.files.find(row=>row.role===role);
    need(file&&selected.bytes===file.bytes&&selected.sha256===file.sha256,
      'The prepared review selects a different complete '+name+'.');
  }
  const originalApplication=prepared.files.find(row=>row.sha256===prepared.selection.application.sha256);
  need(originalApplication&&await sha256(originalApplication.content)===originalApplication.sha256,
    'Retain the complete application read by the original reviewer.');
  const expected=new Map(submission.parseAnswers(originalApplication.content).map(row=>[row.id,row.text]));
  let view=await review.reviewRoundView(round);
  need(view.draft.currentSource===prepared.selection.application.sha256,
    'Review the actual selected current application source.');
  need(view.participants.some(row=>row.id===actorId),'Retain the existing receiving reviewer.');
  const initialEvents=round.events.length,selectedEdition=view.selectedEdition;
  const result={preparedSha256,applicationSha256:prepared.selection.application.sha256,
    selectedEdition,decisions:[],resolutions:[],pending:[],actions:[]};
  const unchanged=id=>view.draft.answers.find(row=>row.id===id)?.text===expected.get(id);
  const changedIds=ids=>ids.filter(id=>!unchanged(id));
  const identify=async(kind,key)=>'SCF-PREPARED-A8CE-'+await sha256(JSON.stringify({
    preparedSha256,selectedEdition,actorId,kind,key
  }));
  async function apply(kind,input,key){
    const requestId=await identify(kind,key);
    const original=round.events.find(event=>event.id===requestId);
    round=await review.applyReviewAction(round,{
      requestId,expectedRevision:original?.expectedRevision??round.events.length,
      actorId,kind,input,at
    });
    await onCheckpoint(await review.exportReviewRound(round,{now:at}));
    view=await review.reviewRoundView(round);result.actions.push(requestId);
  }
  async function open(){
    if(view.status==='COMPLETE')await apply('reopen',{
      note:'Record the original authors’ complete source-specific review for the selected current application, preserving its prior review and all original history.'
    },'current-authored-review');
  }
  for(const item of prepared.decision_notes){
    need(item.applicationSha256===prepared.selection.application.sha256,'Keep each authored decision with its original application.');
    const target=view.targets.find(row=>same(row.target,item.target));
    const ids=item.target.kind==='answer'?[item.target.id]:
      item.target.kind==='requirement'?(view.draft.reviews.find(row=>row.id===item.target.id)?.answers||[]):
      [...expected.keys()];
    const changed=changedIds(ids);
    if(!target||changed.length){result.pending.push({kind:'decision',target:item.target,
      reason:target?'retained-authored-answer-differs':'target-absent',answerIds:changed});continue;}
    const requestId=await identify('review',item.target);
    const current=view.decisions.find(row=>row.actorId===actorId&&same(row.target,item.target));
    const matches=current&&current.bindingSha256===target.bindingSha256&&current.decision===item.decision&&
      current.note===item.note&&same(current.references,item.references||[]);
    if(!matches){
      if(round.events.some(event=>event.id===requestId)){
        result.pending.push({kind:'decision',target:item.target,reason:'a-later-original-review-decision-is-current'});continue;
      }
      await open();
      await apply('review',{editionId:view.selectedEdition,target:item.target,
        bindingSha256:target.bindingSha256,decision:item.decision,note:item.note,
        references:item.references||[]},item.target);
    }
    const actual=view.decisions.find(row=>row.actorId===actorId&&same(row.target,item.target));
    need(actual&&actual.note===item.note&&actual.bindingSha256===target.bindingSha256,
      'Retain the complete authored decision on its exact current target.');
    result.decisions.push({target:item.target,id:actual.id,decision:actual.decision,
      bindingSha256:actual.bindingSha256,noteSha256:await sha256(actual.note),
      referencesSha256:await sha256(JSON.stringify(actual.references)),reused:!!matches});
  }
  for(const item of prepared.request_resolutions){
    need(item.applicationSha256===prepared.selection.application.sha256,'Keep each prepared resolution with its original source.');
    const matches=view.changes.filter(row=>row.id.endsWith(':'+item.request_suffix));
    const changed=changedIds(item.answer_ids);
    const selectedText=item.answer_ids.map(id=>view.draft.answers.find(row=>row.id===id)?.text||'').join('\n\n');
    const missing=item.excerpts.filter(text=>!selectedText.includes(text));
    if(matches.length!==1||changed.length||missing.length){
      result.pending.push({kind:'resolution',requestSuffix:item.request_suffix,
        reason:matches.length!==1?'original-request-not-unique':changed.length?'retained-authored-answer-differs':'current-excerpt-differs',
        answerIds:changed,missingExcerpts:missing});continue;
    }
    const change=matches[0],note=item.resolution;
    const current=change.resolutions.at(-1);
    const reused=change.status==='resolved'&&current?.note===note&&current.editionId===selectedEdition;
    if(!reused){
      const key=await identify('resolve',change.id);
      if(round.events.some(event=>event.id===key)){
        result.pending.push({kind:'resolution',changeId:change.id,reason:'a-later-original-resolution-is-current'});continue;
      }
      await open();await apply('resolve',{changeId:change.id,editionId:view.selectedEdition,
        status:'resolved',note},change.id);
    }
    const actual=view.changes.find(row=>row.id===change.id);
    need(actual.status==='resolved'&&actual.resolutions.at(-1)?.note===note,
      'Retain the current authored resolution in the original request.');
    result.resolutions.push({changeId:change.id,id:actual.resolutions.at(-1).id,
      noteSha256:await sha256(note),reused});
  }
  if(!view.readiness.length&&!result.pending.length&&view.status!=='COMPLETE'){
    await apply('finish',{editionId:view.selectedEdition,outcome:'ready-for-author-check',
      note:'The selected complete source package, all current original targets and the five original technical requests have the original authors’ source-specific review. Complete source, authored history, field and planning bindings, original review events and prepared outputs remain in the same customer case.'
    },'current-authored-review');
  }
  result.actionsAdded=round.events.length-initialEvents;result.reviewActions=round.events.length;
  result.reviewStatus=view.status;result.readiness=view.readiness;
  return {round,view,exported:await review.exportReviewRound(round,{now:at}),
    report:await review.reviewReport(round),preparedReview:result};
}

