// Shared catalog structure and search metadata. Payment admission remains with the catalog owner.
import { inspectResourceURL, inspectRouteTemplate } from '../../stellar-forge/route-identity/identity.mjs';

const plain = (v) => v !== null && typeof v === 'object' && !Array.isArray(v);
const printable = (v) => typeof v === 'string' && v.length > 0 && v.length <= 32 && /^[\x20-\x7E]+$/.test(v);
const MCP_TOOL_NAME = /^[A-Za-z0-9_.-]{1,128}$/;

export function sanitizeResourceSearchMetadata(resource) {
  const result = { ...resource };
  if (!printable(result.serviceName)) delete result.serviceName;
  if (!Array.isArray(result.tags)) delete result.tags;
  else {
    const seen = new Set();
    result.tags = result.tags.filter(t => {
      if (!printable(t) || seen.has(t.toLowerCase())) return false;
      seen.add(t.toLowerCase());
      return seen.size <= 5;
    }).slice(0, 5);
  }
  return result;
}

function keyOf(entry) {
  const info = entry.extensions?.bazaar?.info?.input;
  if (!plain(info) || !['http','mcp'].includes(info.type)) throw new TypeError('Valid HTTP or MCP Bazaar info required');
  // Reject raw encoded traversal before WHATWG URL normalization.
  const checked = inspectResourceURL(entry.resource?.url);
  if (!checked.ok) throw new TypeError(`Invalid resource URL: ${checked.reason}`);
  const url = checked.url;
  if (info.type === 'mcp') {
    if (typeof info.toolName !== 'string' || !MCP_TOOL_NAME.test(info.toolName) || !plain(info.inputSchema)) throw new TypeError('Invalid MCP tool');
    return ['mcp',url.href,info.toolName].join('|');
  }
  if (!['GET','HEAD','DELETE','POST','PUT','PATCH'].includes(info.method)) throw new TypeError('Invalid HTTP method');
  // Different concrete path parameter values collapse to the same canonical entry.
  const template = inspectRouteTemplate(entry.extensions.bazaar.routeTemplate);
  const path = template.ok ? template.canonicalPath : url.pathname;
  return ['http',url.origin,path,url.search,info.method].join('|');
}


/** The exact existing envelope checks and canonical catalog key. */
export function validateCatalogEntryIdentity(entry) {
  if (!plain(entry?.resource) || !Array.isArray(entry.accepts) || entry.accepts.length === 0 ||
      !plain(entry.extensions?.bazaar) || !plain(entry.extensions.bazaar.info) ||
      !plain(entry.extensions.bazaar.schema)) throw new TypeError('Missing validated Bazaar envelope');
  if (entry.accepts.some(a => !plain(a) || typeof a.network !== 'string' || typeof a.scheme !== 'string' || typeof a.payTo !== 'string')) throw new TypeError('Invalid payment terms');
  return keyOf(entry);
}

/** Detached fields for search. Icons and pricing remain with their original
 * consumers; this read projection never fetches an icon or authorizes payment. */
export function projectCatalogSearchEntry(entry) {
  const id = validateCatalogEntryIdentity(entry), projected = structuredClone(entry);
  projected.resource = sanitizeResourceSearchMetadata(projected.resource);
  return { id, entry: projected };
}

// MIT. Private read-side acceleration for the authoritative BazaarCatalog Map.
// Indexes narrow candidates; they never validate, admit, retire or pay for an offer.
import { BazaarRankingIndex } from './ranking.mjs';

const PAYMENT_KEYS = ['payTo', 'network', 'scheme', 'asset'];
const MAX_RESULTS = 64;
const MAX_REFERENCES = 200_000;

function matches(row, filters) {
  if (Object.hasOwn(filters, 'type') && row.extensions?.bazaar?.info?.input?.type !== filters.type) return false;
  if (Object.hasOwn(filters, 'extensions') && !Object.hasOwn(row.extensions, filters.extensions)) return false;
  // Intersecting per-field postings is only a candidate reduction: all payment
  // fields MUST still match the SAME original accepted option, never a hybrid.
  const keys = PAYMENT_KEYS.filter(key => Object.hasOwn(filters, key));
  return !keys.length || row.accepts.some(option =>
    keys.every(key => option?.[key] === filters[key]));
}

function dimensions(row) {
  const result = new Map([
    ['type', new Set([row.extensions?.bazaar?.info?.input?.type])],
    ['extensions', new Set(Object.keys(row.extensions))],
  ]);
  for (const key of PAYMENT_KEYS) result.set(key, new Set(row.accepts
    .map(option => option[key]).filter(value => typeof value === 'string')));
  return result;
}

/** Internal ownership contract: entries and returned row references stay inside
 * BazaarCatalog. Its public reads clone pages. Call changed AFTER each Map write;
 * a catalog clone owns a fresh Map and a fresh index, never another clone's cache.
 */
export class CatalogQueryIndex {
  #entries;
  #ranking;
  #postings = new Map();
  #ordinals = new Map();
  #nextOrdinal = 0;
  #ready = false;
  #ordered = null;
  #cache = new Map();
  #references = 0;
  #counts = { indexBuilds: 0, orderBuilds: 0, candidateChecks: 0,
    listHits: 0, listMisses: 0, searchHits: 0, searchMisses: 0, rankRuns: 0,
    evictions: 0, invalidations: 0 };

  constructor(entries) {
    this.#entries = entries;
    this.#ranking = new BazaarRankingIndex(entries);
  }

  #post(id, row, add) {
    for (const [field, values] of dimensions(row)) {
      let fieldIndex = this.#postings.get(field);
      if (!fieldIndex && add) this.#postings.set(field, fieldIndex = new Map());
      if (!fieldIndex) continue;
      for (const value of values) {
        let ids = fieldIndex.get(value);
        if (add) {
          if (!ids) fieldIndex.set(value, ids = new Set());
          ids.add(id);
        } else if (ids) {
          ids.delete(id);
          if (!ids.size) fieldIndex.delete(value);
        }
      }
      if (!fieldIndex.size) this.#postings.delete(field);
    }
  }

  #ensureIndex() {
    if (this.#ready) return;
    for (const [id, row] of this.#entries) {
      this.#ordinals.set(id, this.#nextOrdinal++);
      this.#post(id, row, true);
    }
    this.#ready = true;
    this.#counts.indexBuilds++;
  }

  changed(id, before, after) {
    this.#ranking.changed(id, before, after);
    // An update replaces the Map's value without changing its insertion order.
    // Delete/reinsert DOES get a new ordinal, exactly like the original Map.
    if (this.#ready) {
      if (before !== undefined) this.#post(id, before, false);
      if (after !== undefined) {
        if (before === undefined) this.#ordinals.set(id, this.#nextOrdinal++);
        this.#post(id, after, true);
      } else this.#ordinals.delete(id);
    }
    if (before === undefined || after === undefined) this.#ordered = null;
    this.#cache.clear();
    this.#references = 0;
    this.#counts.invalidations++;
  }

  #candidateIds(filters) {
    const fields = Object.entries(filters);
    if (!fields.length) return [...this.#entries.keys()];
    this.#ensureIndex();
    const sets = [];
    for (const [field, value] of fields) {
      const ids = this.#postings.get(field)?.get(value);
      if (!ids) return [];
      sets.push(ids);
    }
    sets.sort((a, b) => a.size - b.size);
    const [smallest, ...rest] = sets, result = [];
    for (const id of smallest) {
      if (!rest.every(ids => ids.has(id))) continue;
      this.#counts.candidateChecks++;
      if (matches(this.#entries.get(id), filters)) result.push(id);
    }
    return result;
  }

  #memo(kind, filters, query, compute) {
    // Offset, limit and cursor select a page, not a different result set. The
    // caller checks cursor generation BEFORE this lookup; hits cannot revive it.
    const key = JSON.stringify([kind, query, Object.entries(filters).sort(([a], [b]) => a.localeCompare(b))]);
    const hit = this.#cache.get(key);
    if (hit !== undefined) {
      this.#cache.delete(key); this.#cache.set(key, hit);
      this.#counts[kind + 'Hits']++;
      return hit;
    }
    this.#counts[kind + 'Misses']++;
    const result = compute(); // Invalid queries are not retained as cache entries.
    if (result.length <= MAX_REFERENCES) {
      while (this.#cache.size >= MAX_RESULTS || this.#references + result.length > MAX_REFERENCES) {
        const oldest = this.#cache.keys().next().value;
        this.#references -= this.#cache.get(oldest).length;
        this.#cache.delete(oldest); this.#counts.evictions++;
      }
      this.#cache.set(key, result); this.#references += result.length;
    }
    return result;
  }

  list(filters) {
    return this.#memo('list', filters, null, () => {
      let ids;
      if (!Object.keys(filters).length) {
        if (this.#ordered === null) {
          this.#ordered = [...this.#entries.keys()].sort((a, b) => a.localeCompare(b));
          this.#counts.orderBuilds++;
        }
        ids = this.#ordered;
      } else {
        ids = this.#candidateIds(filters);
        // Locale comparison can tie for distinct Unicode keys. Use Map insertion
        // order for that tie, matching the original stable full-catalog sort.
        ids.sort((a, b) => a.localeCompare(b) || this.#ordinals.get(a) - this.#ordinals.get(b));
      }
      return ids.map(id => this.#entries.get(id));
    });
  }

  search(filters, query) {
    return this.#memo('search', filters, query, () => {
      const ids = this.#candidateIds(filters);
      // Preserve the original corpus iteration order as well as corpus membership:
      // ranking's floating-point reductions and stable ties must remain identical.
      if (Object.keys(filters).length) ids.sort((a, b) => this.#ordinals.get(a) - this.#ordinals.get(b));
      this.#counts.rankRuns++;
      return this.#ranking.rank(ids, query).map(item => item.row);
    });
  }

  get stats() {
    return { ...this.#counts, ...this.#ranking.stats, indexedEntries: this.#ready ? this.#ordinals.size : 0,
      cachedResults: this.#cache.size, cachedReferences: this.#references,
      maxCachedResults: MAX_RESULTS, maxCachedReferences: MAX_REFERENCES };
  }
}

// MIT. Deterministic, dependency-free lexical/fuzzy ranking for validated x402 Bazaar records.
// This module only reads already trusted catalog rows; it never ingests payment payloads.
const STOP = new Set([
  'a','an','and','are','can','could','find','for','get','give','i','in','is','me',
  'my','of','on','or','please','show','that','the','to','want','which','with','you'
]);
const NORMALIZE = s => String(s ?? '').normalize('NFKD').replace(/\p{M}/gu, '').toLowerCase();
export const tokenize = s => NORMALIZE(s).match(/[\p{L}\p{N}]+/gu) ?? [];
const words = s => tokenize(typeof s === 'string' ? s.slice(0,2048) : '');
const object = o => o !== null && typeof o === 'object' && !Array.isArray(o);
const field = (text, weight) => ({ tokens: words(text).slice(0,128), weight });

// Input annotations share the original parameter field's 2048-character /
// 128-token budget. Walk only request schemas that the seller actually emits.
// Request examples, defaults and response payloads do not contribute terms.
const SCHEMA_NODES = 128;
const SCHEMA_DEPTH = 16;
const SCHEMA_CHILDREN = 32;
const PARAMETER_CHARS = 2048;
const HTTP_PARAMETER_GROUPS = ['queryParams', 'body', 'pathParams', 'headers'];

function localSchemaReference(root, reference) {
  if (typeof reference !== 'string' || reference.length > 2048 ||
      !reference.startsWith('#')) return null;
  let pointer;
  try { pointer = decodeURIComponent(reference.slice(1)); }
  catch { return null; }
  if (pointer === '') return root;
  if (!pointer.startsWith('/')) return null;
  const parts = pointer.slice(1).split('/');
  if (parts.length > SCHEMA_DEPTH * 2) return null;
  let node = root;
  for (const part of parts) {
    if (/~(?:[^01]|$)/.test(part)) return null;
    const key = part.replace(/~1/g, '/').replace(/~0/g, '~');
    if (node === null || typeof node !== 'object' || !Object.hasOwn(node, key)) return null;
    node = node[key];
  }
  return object(node) ? node : null;
}

function schemaAlternatives(schema, root) {
  const alternatives = [];
  const reference = localSchemaReference(root, schema.$ref);
  if (reference) alternatives.push(reference);
  for (const keyword of ['allOf', 'anyOf', 'oneOf']) {
    if (Array.isArray(schema[keyword]))
      alternatives.push(...schema[keyword].slice(0, SCHEMA_CHILDREN).filter(object));
  }
  return alternatives;
}

/** Locate the actual HTTP input groups, including composed/local-ref containers. */
function httpParameterSchemas(root) {
  if (!object(root)) return [];
  const queue = [{ schema: root, step: 0, depth: 0 }], result = [];
  const seen = new WeakMap();
  const enqueue = (schema, step, depth) => {
    if (object(schema) && depth <= SCHEMA_DEPTH && queue.length < SCHEMA_NODES)
      queue.push({ schema, step, depth });
  };
  for (let at = 0; at < queue.length; at++) {
    const { schema, step, depth } = queue[at];
    const visits = seen.get(schema) ?? new Set();
    if (visits.has(step)) continue;
    visits.add(step); seen.set(schema, visits);
    if (step === 2) { result.push(schema); continue; }
    const properties = object(schema.properties) ? schema.properties : {};
    for (const name of step === 0 ? ['input'] : HTTP_PARAMETER_GROUPS)
      if (Object.hasOwn(properties, name)) enqueue(properties[name], step + 1, depth + 1);
    for (const alternative of schemaAlternatives(schema, root))
      enqueue(alternative, step, depth + 1);
  }
  return result;
}

/**
 * Breadth-first traversal keeps top-level parameters ahead of deep schemas.
 * Local JSON pointers resolve only inside their original schema document;
 * unreachable definitions and remote references do not contribute terms.
 */
function inputParameterText(row, input) {
  const bazaarSchema = row.extensions?.bazaar?.schema;
  const roots = input.type === 'http'
    ? httpParameterSchemas(bazaarSchema).map(schema => ({ schema, root: bazaarSchema }))
    : object(input.inputSchema) ? [{ schema: input.inputSchema, root: input.inputSchema }] : [];
  const queue = [], seen = new WeakSet();
  let text = '';
  const append = value => {
    if (typeof value !== 'string' || !value.length) return;
    const separator = text.length ? ' ' : '';
    const available = PARAMETER_CHARS - text.length - separator.length;
    if (available > 0) text += separator + value.slice(0, available);
  };
  const enqueue = (schema, root, depth, name = '') => {
    if (depth <= SCHEMA_DEPTH && queue.length < SCHEMA_NODES && (object(schema) || name))
      queue.push({ schema, root, depth, name });
  };
  for (const { schema, root } of roots) enqueue(schema, root, 0);
  for (let at = 0; at < queue.length && text.length < PARAMETER_CHARS; at++) {
    const { schema, root, depth, name } = queue[at];
    append(name);
    if (!object(schema) || seen.has(schema)) continue;
    seen.add(schema);
    append(schema.description);
    append(schema.title);
    if (object(schema.properties)) {
      let count = 0;
      for (const property in schema.properties) {
        if (!Object.hasOwn(schema.properties, property)) continue;
        if (count++ === SCHEMA_CHILDREN) break;
        enqueue(schema.properties[property], root, depth + 1, property);
      }
    }
    for (const alternative of schemaAlternatives(schema, root))
      enqueue(alternative, root, depth + 1);
    const items = Array.isArray(schema.items) ? schema.items.slice(0, SCHEMA_CHILDREN) : [schema.items];
    for (const item of items) enqueue(item, root, depth + 1);
    if (Array.isArray(schema.prefixItems))
      for (const item of schema.prefixItems.slice(0, SCHEMA_CHILDREN)) enqueue(item, root, depth + 1);
    for (const keyword of ['additionalProperties', 'unevaluatedProperties'])
      enqueue(schema[keyword], root, depth + 1);
    if (object(schema.patternProperties)) {
      let count = 0;
      for (const pattern in schema.patternProperties) {
        if (!Object.hasOwn(schema.patternProperties, pattern)) continue;
        if (count++ === SCHEMA_CHILDREN) break;
        enqueue(schema.patternProperties[pattern], root, depth + 1);
      }
    }
  }
  return text;
}

function toFields(row) {
  const resource = object(row.resource) ? row.resource : {};
  const info = object(row.extensions?.bazaar?.info) ? row.extensions.bazaar.info : {};
  const input = object(info.input) ? info.input : {};
  const parameters = inputParameterText(row, input);
  return [
    field(resource.serviceName, 9),
    field(Array.isArray(resource.tags) ? resource.tags.filter(x => typeof x === 'string').slice(0,16).join(' ') : '', 7),
    field(input.toolName, 8),
    field(input.description, 4),
    field(resource.description, 4),
    field(parameters, 2),
    field(resource.url, 0.6)
  ];
}

// Small, bounded edit distance prevents a misspelled merchant/tool name from vanishing.
// Never uses fuzzy scores as proof of semantic equivalence.
function editDistanceWithin(a, b, limit) {
  if (Math.abs(a.length - b.length) > limit) return false;
  if (a === b) return true;
  // The caller permits at most one or two substitutions/insertions/deletions.
  // Cells farther than `limit` from the diagonal cannot change the answer;
  // only allocate/visit that narrow band, rather than O(a.length*b.length).
  const beyond = limit + 1;
  const n = b.length;
  let previousStart = 0;
  let previousEnd = Math.min(n, limit);
  let previous = Array.from({length:previousEnd+1}, (_,j)=>j);
  for (let i=1;i<=a.length;i++) {
    const start = Math.max(0, i-limit);
    const end = Math.min(n, i+limit);
    const current = new Array(end-start+1);
    let rowMin = beyond;
    for (let j=start;j<=end;j++) {
      let value;
      if (j === 0) value = i;
      else {
        const above = j >= previousStart && j <= previousEnd
          ? previous[j-previousStart] + 1 : beyond;
        const left = j > start ? current[j-1-start] + 1 : beyond;
        const diagonal = j-1 >= previousStart && j-1 <= previousEnd
          ? previous[j-1-previousStart] + (a[i-1] === b[j-1] ? 0 : 1) : beyond;
        value = Math.min(above, left, diagonal);
      }
      current[j-start] = value;
      if (value < rowMin) rowMin = value;
    }
    if (rowMin > limit) return false;
    previous = current;
    previousStart = start;
    previousEnd = end;
  }
  return b.length >= previousStart && b.length <= previousEnd &&
    previous[b.length-previousStart] <= limit;
}

export function analyzeQuery(query) {
  if (typeof query !== 'string' || !query.trim() || query.length > 1024) throw new RangeError('query is required (max 1024 chars)');
  const raw = [...new Set(words(query))].slice(0,32);
  if (!raw.length) throw new RangeError('query requires searchable terms');
  const meaningful = raw.filter(t=>!STOP.has(t));
  return meaningful.length ? meaningful : raw;
}

function prepareDocument(key, row, indexFuzzy = false) {
  const fields = toFields(row).map(f => {
    const tf = new Map();
    for (const t of f.tokens) tf.set(t, (tf.get(t) ?? 0) + 1);
    return { ...f, tf };
  });
  return { key, row, fields,
    vocabulary: new Set(fields.flatMap(f => [...f.tf.keys()])),
    fuzzyVocabulary: indexFuzzy ? new Set(fields.slice(0, 5).flatMap(f =>
      [...f.tf.keys()].filter(t => t.length >= 5))) : null };
}

function averageLengths(docs) {
  return docs[0].fields.map((_, i) =>
    Math.max(1, docs.reduce((sum, d) => sum + d.fields[i].tokens.length, 0) / docs.length));
}

// Both the one-shot API and the catalog index use this exact scoring path.
// The corpus statistics include EVERY filtered row, even rows with no match.
function rankPreparedDocuments(documents, q, avg, df, total, fuzzyMatches = null) {
  const ranked = [];
  for (const prepared of documents) {
    const doc = { ...prepared, fields: prepared.fields.map((f, i) => ({
      ...f, normalizedWeight: f.weight / (0.25 + 0.75 * f.tokens.length / avg[i])
    })) };
    let score = 0, coverage = 0, exactHits = 0;
    for (const t of q) {
      let weighted = 0;
      for (const f of doc.fields) weighted += Math.min(3, f.tf.get(t) ?? 0) * f.normalizedWeight;
      if (weighted) { coverage++; exactHits++; }
      else if (t.length >= 5) {
        let best = 0;
        const limit = t.length >= 8 ? 2 : 1;
        const matchingTerms = fuzzyMatches?.get(t);
        for (const f of doc.fields.slice(0, 5)) for (const v of f.tf.keys()) {
          if (v.length < 5 || v[0] !== t[0] ||
              (matchingTerms ? !matchingTerms.has(v) : !editDistanceWithin(t, v, limit))) continue;
          best = Math.max(best, 0.22 * f.normalizedWeight);
        }
        weighted = best;
        if (best) coverage++;
      }
      if (weighted) {
        const idf = Math.log1p((total - (df.get(t) ?? 0) + 0.5) / ((df.get(t) ?? 0) + 0.5));
        score += idf * (2.2 * weighted / (1.2 + weighted));
      }
    }
    if (!coverage) continue;
    const phrase = q.join(' ');
    const hasPhrase = q.length >= 2 &&
      doc.fields.slice(0, 5).some(f => f.tokens.join(' ').includes(phrase));
    score *= 1 + 0.45 * coverage / q.length;
    if (hasPhrase) score += 1.4;
    if (exactHits === q.length) score += 0.4;
    ranked.push({ key: doc.key, row: doc.row, score });
  }
  return ranked.sort((a, b) => b.score - a.score || a.key.localeCompare(b.key));
}

/**
 * Rank already-validated [canonicalKey, row] pairs. Corpus statistics come from
 * these exact entries. The one-shot API owns no persistent cache and never
 * mutates the supplied rows. Payment and ownership filters remain upstream.
 */
export function rankBazaarEntries(entries, query) {
  const q = analyzeQuery(query);
  const docs = [...entries].map(([key, row]) => prepareDocument(key, row));
  if (!docs.length) return [];
  const avg = averageLengths(docs);
  const df = new Map(q.map(t => [t, 0]));
  for (const doc of docs)
    for (const t of q) if (doc.vocabulary.has(t)) df.set(t, df.get(t) + 1);
  return rankPreparedDocuments(docs, q, avg, df, docs.length);
}

/**
 * Catalog-owned lexical state. Rows belong to the authoritative Map and are
 * replaced, never mutated in place. changed() follows each Map write. A clone
 * owns a fresh index. No row, query text or posting is exposed by diagnostics.
 */
export class BazaarRankingIndex {
  #entries;
  #docs = new Map();
  #postings = new Map();
  #fuzzyUses = new Map();
  #fuzzyBuckets = new Map();
  #lengths = Array(7).fill(0);
  #references = 0;
  #ready = false;
  #counts = { rankingIndexBuilds: 0, rankingPreparedRows: 0,
    rankingQueries: 0, rankingCorpusRows: 0, rankingCandidateRows: 0,
    rankingTermLookups: 0, rankingFuzzyComparisons: 0 };

  constructor(entries) { this.#entries = entries; }

  #add(id, row) {
    const doc = prepareDocument(id, row, true);
    this.#docs.set(id, doc);
    for (let i = 0; i < this.#lengths.length; i++)
      this.#lengths[i] += doc.fields[i].tokens.length;
    for (const term of doc.vocabulary) {
      let ids = this.#postings.get(term);
      if (!ids) this.#postings.set(term, ids = new Set());
      ids.add(id); this.#references++;
    }
    for (const term of doc.fuzzyVocabulary) {
      const previous = this.#fuzzyUses.get(term) ?? 0;
      this.#fuzzyUses.set(term, previous + 1);
      if (previous) continue;
      let lengths = this.#fuzzyBuckets.get(term[0]);
      if (!lengths) this.#fuzzyBuckets.set(term[0], lengths = new Map());
      let terms = lengths.get(term.length);
      if (!terms) lengths.set(term.length, terms = new Set());
      terms.add(term);
    }
    this.#counts.rankingPreparedRows++;
  }

  #remove(id) {
    const doc = this.#docs.get(id);
    if (!doc) return;
    for (let i = 0; i < this.#lengths.length; i++)
      this.#lengths[i] -= doc.fields[i].tokens.length;
    for (const term of doc.vocabulary) {
      const ids = this.#postings.get(term);
      ids.delete(id); this.#references--;
      if (!ids.size) this.#postings.delete(term);
    }
    for (const term of doc.fuzzyVocabulary) {
      const count = this.#fuzzyUses.get(term) - 1;
      if (count) this.#fuzzyUses.set(term, count);
      else {
        this.#fuzzyUses.delete(term);
        const lengths = this.#fuzzyBuckets.get(term[0]), terms = lengths.get(term.length);
        terms.delete(term);
        if (!terms.size) lengths.delete(term.length);
        if (!lengths.size) this.#fuzzyBuckets.delete(term[0]);
      }
    }
    this.#docs.delete(id);
  }

  #ensure(ids) {
    if (!this.#ready) {
      this.#ready = true;
      this.#counts.rankingIndexBuilds++;
    }
    // A first selective search prepares only its selected rows. Later queries
    // reuse those fields and add newly selected rows as needed.
    for (const id of ids) if (!this.#docs.has(id)) {
      const row = this.#entries.get(id);
      if (row === undefined) throw new RangeError('Unknown internal catalog key');
      this.#add(id, row);
    }
  }

  changed(id, before, after) {
    // Unsearched rows need no lexical work on writes. A prepared replacement
    // updates only its own postings; retirement releases its retained fields.
    if (!this.#docs.has(id)) return;
    this.#remove(id);
    if (after !== undefined) this.#add(id, after);
  }

  #fuzzyMatches(term) {
    const matches = new Set();
    if (term.length < 5) return matches;
    const limit = term.length >= 8 ? 2 : 1;
    const lengths = this.#fuzzyBuckets.get(term[0]);
    if (!lengths) return matches;
    for (let length = Math.max(5, term.length - limit); length <= term.length + limit; length++) {
      for (const word of lengths.get(length) ?? []) {
        this.#counts.rankingFuzzyComparisons++;
        if (editDistanceWithin(term, word, limit)) matches.add(word);
      }
    }
    return matches;
  }

  rank(ids, query) {
    const q = analyzeQuery(query);
    this.#counts.rankingQueries++;
    this.#counts.rankingCorpusRows += ids.length;
    if (!ids.length) return [];
    this.#ensure(ids);
    // ids is the complete, unique subset selected by CatalogQueryIndex, not a
    // lexical shortlist. When it selects all prepared rows, statistics can
    // reuse maintained totals, even if other catalog rows remain unsearched.
    const all = ids.length === this.#docs.size;
    const selected = all ? null : new Set(ids);
    const inCorpus = id => selected === null || selected.has(id);
    const avg = all ? this.#lengths.map(sum => Math.max(1, sum / ids.length))
      : averageLengths(ids.map(id => this.#docs.get(id)));
    const df = new Map(), candidates = new Set(), fuzzy = new Map();
    const addPosting = term => {
      this.#counts.rankingTermLookups++;
      for (const id of this.#postings.get(term) ?? [])
        if (inCorpus(id)) candidates.add(id);
    };
    for (const term of q) {
      const posting = this.#postings.get(term);
      let frequency = 0;
      if (posting) {
        if (all) frequency = posting.size;
        else for (const id of posting) if (selected.has(id)) frequency++;
      }
      df.set(term, frequency);
      addPosting(term);
      const matches = this.#fuzzyMatches(term);
      fuzzy.set(term, matches);
      // A global posting can include a URL-only occurrence. Keeping that row is
      // conservative: the common scorer still fuzzes only the original fields.
      for (const word of matches) if (word !== term) addPosting(word);
    }
    // Keep the supplied corpus order, including replacement and delete/reinsert
    // behavior and locale ties. No query-dependent preparation order can leak.
    const docs = ids.filter(id => candidates.has(id)).map(id => this.#docs.get(id));
    this.#counts.rankingCandidateRows += docs.length;
    return rankPreparedDocuments(docs, q, avg, df, ids.length, fuzzy);
  }

  get stats() {
    return { ...this.#counts, rankingDocuments: this.#docs.size,
      rankingUniqueTerms: this.#postings.size, rankingFuzzyTerms: this.#fuzzyUses.size,
      rankingStoredTokens: this.#lengths.reduce((sum, n) => sum + n, 0),
      rankingPostingReferences: this.#references };
  }
}

import {parseOffer} from './offer.mjs';
import {zipWorkspace} from './onboarding.mjs';

export const AGENTSMITH_SCHEMA = 'stellar-forge.frontdoor-agentsmith.v1';
export const AGENTSMITH_ASSET = 'CBIELTK6YBZJU5UP2WWQEUCYKLPU6AUNZ2BQ4WWFEIE3USCIHMXQDAMA';
export const AGENTSMITH_SOURCE = Object.freeze({
  capturePath: 'stellar/scf-starforge-20261009/partners/agentsmith/capture.py',
  captureSha256: '93214bc738c9ad92c70aadddb07655d86ea7e304ea7ed1afda0e5c6b4a940098',
  capturedBundleSha256: '18d45f986bc0f53292086f715f8dbafc5cbf92a59f5fb599c0034285d97103a8',
  sourceCommit: 'aea13f36c6bddf09fcc16cc3825094d1d30cfbb9',
  walletSourceCommit: 'c3f1f9a930e1a4b08a6d60f5643b98ba2f4a0e1d'
});
const encoder = new TextEncoder();
const object = value => value && typeof value === 'object' && !Array.isArray(value);
const need = (value, message) => { if (!value) throw new Error(message); };
export const sha256 = async text => Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',
  typeof text === 'string' ? encoder.encode(text) : text)), byte => byte.toString(16).padStart(2, '0')).join('');
function https(value) {
  need(typeof value === 'string' && value.length < 8192, 'The capture needs its original HTTPS URL.');
  const url = new URL(value);
  need(url.protocol === 'https:' && !url.username && !url.password && !url.hash,
    'Use the original credential-free HTTPS resource.');
  return value;
}

export async function readAgentSmithBundle(text) {
  need(typeof text === 'string' && encoder.encode(text).length <= 24 * 1024 * 1024,
    'Import one complete source bundle of at most 24 MiB.');
  const bundle = JSON.parse(text);
  need(object(bundle) && bundle.schema === 'commons.agentsmith.http-bundle.v1',
    'Select an original AgentSmith HTTP source bundle.');
  const seller = https(bundle.seller), facilitator = https(bundle.facilitator);
  const response = bundle.challenge, supported = bundle.supported;
  need(object(response) && object(supported) && typeof bundle.requestUtf8 === 'string',
    'The complete original request and both HTTP responses are required.');
  need(response.status === 402 && response.url === seller && response.method === 'POST' &&
    supported.status === 200 && supported.url === facilitator.replace(/\/$/, '') + '/supported' &&
    supported.method === 'GET', 'The captured resource, methods or HTTP status changed.');
  need(typeof response.bodyUtf8 === 'string' && typeof supported.bodyUtf8 === 'string',
    'Both original response bodies are required.');
  const requestBytes = encoder.encode(bundle.requestUtf8).length;
  need(requestBytes > 0 && requestBytes <= 16 * 1024 * 1024 &&
    response.requestBodyBytes === requestBytes &&
    response.requestBodySha256 === await sha256(bundle.requestUtf8), 'The captured request bytes changed.');
  need(object(JSON.parse(bundle.requestUtf8)), 'The request must be the original JSON object.');
  need(response.bodySha256 === await sha256(response.bodyUtf8) &&
    supported.bodySha256 === await sha256(supported.bodyUtf8), 'The original HTTP response bytes changed.');
  const {offer} = parseOffer(response.headers?.['payment-required']);
  need(offer.x402Version === 2 && offer.resource?.url === seller, 'The original x402 resource binding changed.');
  need(offer.accepts.length <= 32, 'The original receiving capture accepts at most 32 choices.');
  const selected = offer.accepts.map((choice, index) => ({choice, index})).filter(({choice}) =>
    choice.scheme === 'exact' && choice.network === 'stellar:testnet' && choice.asset === AGENTSMITH_ASSET &&
    choice.extra?.areFeesSponsored === true && (choice.extra.paymentFlow ?? 'authorization') === 'authorization');
  need(selected.length === 1, 'The native receiver needs exactly one sponsored exact testnet USDC choice.');
  const {choice, index} = selected[0];
  need(typeof choice.amount === 'string' && /^[1-9][0-9]*$/.test(choice.amount) &&
    BigInt(choice.amount) <= 9223372036854775807n &&
    /^[GC][A-Z2-7]{55}$/.test(choice.payTo) && Number.isInteger(choice.maxTimeoutSeconds) &&
    choice.maxTimeoutSeconds > 0 && choice.maxTimeoutSeconds <= 86400,
    'The original selected amount, recipient or authorization lifetime is invalid.');
  const kinds = JSON.parse(supported.bodyUtf8).kinds;
  need(Array.isArray(kinds) && kinds.some(kind => kind.x402Version === 2 && kind.scheme === 'exact' &&
    kind.network === 'stellar:testnet' && kind.extra?.areFeesSponsored === true),
    'The original facilitator must advertise sponsored exact Stellar testnet.');
  need(typeof response.retrievedAt === 'string' && Number.isFinite(Date.parse(response.retrievedAt)),
    'The original capture timestamp is required.');
  return {text, bundle, offer, selected: choice, acceptIndex: index, requestBytes,
    capturedAt: response.retrievedAt, bundleSha256: await sha256(text)};
}

export function validateAgentSmithInput(input) {
  need(object(input) && input.schema === AGENTSMITH_SCHEMA, 'Open a saved AgentSmith receiving draft.');
  const folder = input.folder?.trim();
  need(typeof folder === 'string' && /^[A-Za-z0-9][A-Za-z0-9._-]{0,79}$/.test(folder) && !['.', '..'].includes(folder),
    'Use a simple packet folder name.');
  const privateDirectory = input.privateDirectory?.trim();
  need(typeof privateDirectory === 'string' && privateDirectory.startsWith('/') && privateDirectory !== '/' &&
    !privateDirectory.endsWith('/') && !/[\u0000-\u001f\u007f\\]/.test(privateDirectory) &&
