  capturePath: 'stellar/scf-starforge-20261009/partners/rail402/capture.py',
  captureSha256: '41d59e5234865c81847bb7bbd1ff02a1c977ab85805d9dfcc6acc1a0d1ceb062',
  sourceCommit: '72c134b1013efd404c6ba77427fc7b58f90e1100',
