.text-link { display: inline-flex; gap: 14px; align-items: center; font-size: 12px; padding: 8px 0; }
.text-button { border: 0; background: none; padding: 8px 0; font-size: 12px; text-decoration: underline; text-underline-offset: 3px; }
.section { padding-top: 54px; padding-bottom: 54px; }
.section-heading { display: flex; justify-content: space-between; gap: 42px; align-items: flex-end; margin-bottom: 25px; }
h2 { font-size: 31px; font-weight: 500; letter-spacing: -.8px; line-height: 1.18; margin: 0; }
.section-heading > p { font-size: 13px; color: var(--muted); max-width: 445px; margin: 0; }
.setup-section { border-top: 1px solid var(--line); padding-top: 32px; }
.setup-loading { border: 1px solid var(--line); padding: 40px; background: #fff; }
.setup-shell { border: 1px solid #aaa; background: #fff; min-width: 0; }
.setup-top { padding: 14px 18px; display: flex; gap: 18px; justify-content: space-between; align-items: center; border-bottom: 1px solid var(--line); }
.setup-title { display: flex; gap: 12px; align-items: baseline; flex-wrap: wrap; min-width: 0; }
