.setup-tabs { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); border-bottom: 1px solid var(--line); background: #f5f5f5; }
.setup-tabs button { border: 0; border-bottom: 3px solid transparent; border-right: 1px solid var(--line); background: transparent; padding: 14px 12px; text-align: left; font-size: 12px; display: flex; gap: 10px; }
.setup-tabs button:last-child { border-right: 0; }
