.setup-tabs button span { font: 11px var(--mono); color: var(--muted); }
.setup-pane { padding: 22px; min-width: 0; }
.setup-pane h3 { font-size: 17px; margin: 0 0 8px; font-weight: 500; }
.pane-intro { font-size: 12px; color: var(--muted); margin: 0 0 20px; max-width: 680px; }
.resource-grid { display: grid; grid-template-columns: 230px minmax(0, 1fr); gap: 24px; }
.resource-sidebar { border-right: 1px solid var(--line); padding-right: 20px; min-width: 0; }
.resource-sidebar > .small-label { margin-bottom: 10px; }
.resource-list { display: flex; flex-direction: column; gap: 4px; margin-bottom: 12px; }
.resource-button { width: 100%; text-align: left; border: 1px solid transparent; background: none; padding: 10px; display: flex; flex-direction: column; gap: 4px; min-width: 0; }
.resource-button[aria-pressed="true"] { border-color: #aaa; background: #eee; }
.resource-button:hover { background: #f3f3f3; }
.resource-button strong { font-size: 12px; font-weight: 500; overflow-wrap: anywhere; }
.resource-button code { color: var(--muted); font-size: 10px; overflow-wrap: anywhere; }
.resource-sidebar .button { width: 100%; }
.resource-sidebar p { color: var(--muted); font-size: 11px; line-height: 1.6; }
.field-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 16px; }
.field { display: flex; flex-direction: column; gap: 6px; min-width: 0; }
.field.full { grid-column: 1 / -1; }
.field > label { font-size: 12px; font-weight: 600; }
.field input, .field textarea, .field select, .setup-select { width: 100%; min-width: 0; border: 1px solid #aaa; border-radius: 0; background: #fff; padding: 9px 10px; font-size: 13px; }
.field textarea { resize: vertical; min-height: 90px; }
.field textarea.code-input { font: 11px/1.65 var(--mono); min-height: 240px; tab-size: 2; }
.field .hint { font-size: 11px; color: var(--muted); margin: 0; }
.field [aria-invalid="true"] { border-color: #222; border-width: 2px; padding: 8px 9px; }
.field-error { font-size: 11px; margin: 0; font-weight: 600; }
.field-error:before { content: '! '; font-family: var(--mono); }
.field-row { display: flex; justify-content: space-between; align-items: center; gap: 12px; flex-wrap: wrap; }
.field-row label { font-size: 12px; font-weight: 600; }
.data-tools { display: flex; gap: 16px; flex-wrap: wrap; }
.data-tools .text-button { padding: 3px 0; font-size: 11px; }
.preview-bar { display: flex; align-items: center; justify-content: space-between; gap: 15px; padding: 11px 0; font-size: 11px; color: var(--muted); }
.table-scroll { overflow: auto; max-width: 100%; border: 1px solid var(--line); }
table { width: 100%; border-collapse: collapse; font-size: 12px; }
th { text-align: left; background: #eee; color: #333; font-size: 11px; font-weight: 500; white-space: nowrap; }
th, td { padding: 10px 12px; border-bottom: 1px solid var(--line); vertical-align: top; }
tr:last-child td { border-bottom: 0; }
td code { font-size: 11px; overflow-wrap: anywhere; }
.data-preview td { max-width: 250px; overflow-wrap: anywhere; }
.editor-foot { display: flex; justify-content: space-between; align-items: center; gap: 18px; margin-top: 18px; border-top: 1px solid var(--line); padding-top: 12px; }
.setup-footer { padding: 14px 18px; border-top: 1px solid var(--line); display: flex; justify-content: space-between; gap: 14px; align-items: center; background: #f8f8f8; }
.setup-footer .small-label { max-width: 60%; line-height: 1.7; }
.setup-footer .button { white-space: nowrap; }
.setup-notice { border: 1px solid var(--line); border-left: 3px solid #666; padding: 12px 15px; font-size: 12px; line-height: 1.7; margin: 18px 0 0; background: #f6f6f6; }
.setup-notice strong { font-weight: 600; }
.setup-errors { border-bottom: 1px solid var(--line); background: #eee; padding: 14px 18px; font-size: 12px; }
.setup-errors h3 { margin: 0 0 8px; font-size: 13px; }
.setup-errors ul { margin: 0; padding-left: 18px; }
.setup-errors button { border: 0; background: none; text-align: left; text-decoration: underline; padding: 3px 0; font-size: 12px; }
.terms-grid { max-width: 800px; }
.review-summary { display: grid; grid-template-columns: repeat(3, minmax(0,1fr)); border: 1px solid var(--line); margin: 18px 0; }
.review-summary > div { padding: 14px 18px; border-right: 1px solid var(--line); min-width: 0; }
.review-summary > div:last-child { border: 0; }
.review-summary strong { display: block; font: 15px var(--mono); margin-top: 6px; overflow-wrap: anywhere; }
.review-bottom { display: grid; grid-template-columns: 220px minmax(0,1fr); gap: 20px; margin-top: 22px; }
.file-list { display: flex; flex-direction: column; gap: 3px; }
.file-list button { padding: 8px 10px; text-align: left; border: 1px solid transparent; background: none; font: 11px var(--mono); overflow-wrap: anywhere; }
.file-list button[aria-pressed="true"] { background: #eee; border-color: #aaa; }
.file-code { background: #f3f3f3; border: 1px solid var(--line); padding: 14px; font: 11px/1.7 var(--mono); margin: 0; max-height: 350px; overflow: auto; }
.review-downloads { margin-top: 20px; display: flex; align-items: center; gap: 20px; flex-wrap: wrap; }
.review-downloads p { margin: 0; font-size: 11px; color: var(--muted); }
.run-step { display: grid; grid-template-columns: 28px minmax(0,1fr); gap: 14px; padding: 18px 0; border-bottom: 1px solid var(--line); }
.run-step:last-child { border: 0; }
.run-number { font: 12px var(--mono); padding-top: 2px; color: var(--muted); }
.run-step h4 { margin: 0 0 7px; font-size: 14px; font-weight: 600; }
.run-step p { margin: 0 0 12px; font-size: 12px; color: var(--muted); }
.command-block { background: #222; color: #f4f4f4; padding: 17px; margin: 0; font: 11px/1.8 var(--mono); max-height: 400px; overflow: auto; }
.run-links { display: flex; gap: 20px; flex-wrap: wrap; margin-top: 10px; }
.run-links a { font-size: 12px; text-decoration: underline; text-underline-offset: 3px; }
.other-workflows { display: flex; gap: 22px; flex-wrap: wrap; padding-top: 18px; align-items: center; }
.other-workflows a { font-size: 12px; text-decoration: underline; text-underline-offset: 3px; }
.drafts-panel { padding: 18px; border-bottom: 1px solid var(--line); background: #f5f5f5; }
.drafts-heading { display: flex; align-items: center; justify-content: space-between; gap: 16px; }
.drafts-heading h3 { margin: 0; font-size: 15px; font-weight: 500; }
.draft-row { display: flex; justify-content: space-between; align-items: center; gap: 18px; padding: 12px 0; border-bottom: 1px solid var(--line); }
.draft-row:last-child { border: 0; }
.draft-row strong { display: block; font-size: 12px; }
.draft-row small { display: block; font-size: 11px; color: var(--muted); }
.draft-row .button { white-space: nowrap; }
.draft-row-actions { display: flex; align-items: center; gap: 14px; }
.setup-status { margin: 0; padding: 10px 18px; border-bottom: 1px solid var(--line); font-size: 12px; background: #eee; overflow-wrap: anywhere; }
/* Original offer inspection and walkthrough */
.workbench { border: 1px solid #aaa; background: #fff; }
.workbench-bar { min-height: 54px; border-bottom: 1px solid var(--line); display: flex; justify-content: space-between; align-items: center; padding: 0 20px; gap: 20px; }
.tab-list { display: flex; gap: 26px; }
.tab-list button { border: 0; border-bottom: 2px solid transparent; background: none; font-size: 12px; padding: 17px 0; }
.tab-list button[aria-selected=true] { border-color: #222; font-weight: 600; }
.local-badge { font-size: 9px; color: var(--muted); }
.status-dot { display: inline-block; width: 5px; height: 5px; background: #666; margin-right: 7px; vertical-align: middle; }
.walkthrough-grid { display: grid; grid-template-columns: .8fr 1.4fr; }
.steps { padding: 18px 16px; border-right: 1px solid var(--line); display: flex; flex-direction: column; gap: 4px; }
.step { background: none; border: 1px solid transparent; display: flex; text-align: left; gap: 15px; align-items: center; padding: 14px 12px; }
.step.active { background: #eee; border-color: #bbb; }
.step:hover { background: #f4f4f4; }
.step-number { font: 11px var(--mono); color: var(--muted); }
.step > span:last-child { margin-left: auto; opacity: 0; }
.step.active > span:last-child { opacity: 1; }
.step strong { display: block; font-size: 12px; font-weight: 500; }
.step small { display: block; font-size: 10px; color: var(--muted); margin-top: 3px; }
.trace { padding: 22px; min-width: 0; display: flex; flex-direction: column; }
.trace-toolbar { display: flex; justify-content: space-between; gap: 10px; font-size: 9px; color: var(--muted); margin-bottom: 12px; }
.trace > pre { background: #222; color: #eee; padding: 20px; font: 11px/1.7 var(--mono); min-height: 185px; max-height: 275px; overflow: auto; margin: 0; }
.trace-note { padding-top: 18px; min-height: 120px; }
.trace-note h3 { font-size: 16px; font-weight: 500; margin: 0 0 7px; }
.trace-note p { font-size: 12px; color: var(--muted); margin: 0; }
.trace-controls { display: flex; justify-content: space-between; align-items: center; margin-top: auto; padding-top: 15px; }
.workbench-foot { border-top: 1px solid var(--line); padding: 13px 20px; display: flex; gap: 20px; align-items: center; color: var(--muted); }
.workbench-foot > .mono { font-size: 9px; white-space: nowrap; }
.workbench-foot p { font-size: 11px; margin: 0; }
.workbench-foot a { text-decoration: underline; }
.inspector-grid { display: grid; grid-template-columns: repeat(2,minmax(0,1fr)); }
.inspect-input { padding: 25px; border-right: 1px solid var(--line); min-width: 0; }
.inspect-input > label { font-size: 18px; font-weight: 500; }
.inspect-input > p { font-size: 12px; color: var(--muted); }
.inspect-input textarea { width: 100%; min-height: 240px; resize: vertical; border: 1px solid #aaa; background: #f8f8f8; padding: 14px; font: 11px/1.7 var(--mono); margin: 18px 0 12px; border-radius: 0; }
.inspector-actions { display: flex; align-items: center; gap: 18px; flex-wrap: wrap; }
.inspect-input .privacy-note { font-size: 11px; margin-top: 17px; }
.inspect-input .error { border-left: 3px solid #555; padding: 9px 12px; background: #eee; }
.inspect-output { padding: 25px; min-width: 0; }
.empty-state { min-height: 330px; display: flex; flex-direction: column; align-items: center; justify-content: center; text-align: center; }
.empty-symbol { font: 28px var(--mono); color: #888; margin-bottom: 22px; }
.empty-state h3 { font-size: 17px; font-weight: 500; margin: 0; }
.empty-state p { font-size: 12px; color: var(--muted); max-width: 290px; margin: 12px 0 24px; }
.empty-state .mono { font-size: 9px; color: #777; }
.result-top { display: flex; justify-content: space-between; flex-wrap: wrap; gap: 10px; align-items: center; }
.outline-pill { display: inline-block; border: 1px solid #aaa; padding: 3px 7px; font-size: 8px; }
.result-resource { border-bottom: 1px solid var(--line); padding: 22px 0 14px; margin-bottom: 16px; }
.result-resource > p { font: 12px/1.7 var(--mono); overflow-wrap: anywhere; margin: 8px 0 0; }
.inspect-output select { width: 100%; margin-top: 9px; border: 1px solid #aaa; padding: 11px; background: #fff; border-radius: 0; font: 11px var(--mono); }
.terms-list { margin: 16px 0; }
.terms-list > div { display: grid; grid-template-columns: 105px minmax(0,1fr); gap: 12px; padding: 10px 0; border-bottom: 1px solid #ddd; font-size: 11px; }
.terms-list dt { color: var(--muted); }
.terms-list dd { margin: 0; font: 11px var(--mono); overflow-wrap: anywhere; }
.offer-notes { font-size: 11px; background: #eee; padding: 12px 15px; margin-top: 20px; }
.offer-notes > p { margin: 0 0 7px; }
.offer-notes > p:last-child { margin: 0; }
.raw-details { margin-top: 22px; border-top: 1px solid var(--line); padding-top: 12px; font-size: 12px; }
.raw-details summary { cursor: pointer; }
.raw-details pre { font: 10px/1.7 var(--mono); max-height: 280px; overflow: auto; padding: 12px; background: #f1f1f1; }
.export-button { margin-top: 12px; }
/* Source-derived commands and component index */
.build-section { background: #eaeaea; border-top: 1px solid var(--line); border-bottom: 1px solid var(--line); }
.workflow-picker { display: grid; grid-template-columns: auto minmax(220px,420px) 1fr; align-items: center; gap: 18px; padding-bottom: 24px; border-bottom: 1px solid #bbb; }
.workflow-picker label { font-size: 13px; font-weight: 600; }
.workflow-picker select { width: 100%; background: #fff; color: #222; border: 1px solid #999; border-radius: 2px; padding: 11px 32px 11px 12px; font: inherit; font-size: 13px; }
.workflow-hint { color: var(--muted); font-size: 11px; }
.command-actions { display: flex; gap: 7px; flex-wrap: wrap; justify-content: flex-end; }
.role-panel { display: grid; grid-template-columns: .9fr 1.15fr; gap: 40px; padding-top: 28px; }
.role-copy .mono { font-size: 10px; color: var(--muted); }
.role-copy h3 { font-size: 24px; font-weight: 500; margin: 13px 0; }
.role-copy > p { font-size: 13px; color: var(--muted); }
.role-copy ol { padding-left: 18px; margin: 20px 0 10px; }
.role-copy li { font-size: 12px; margin-bottom: 9px; }
.terminal { background: #222; color: #eee; min-width: 0; display: flex; flex-direction: column; }
.terminal-bar { padding: 14px 18px; border-bottom: 1px solid #555; display: flex; justify-content: space-between; align-items: center; gap: 10px; font-size: 9px; }
.copy-button { padding: 5px 9px; border: 1px solid #777; color: #eee; background: transparent; font-size: 10px; display: flex; gap: 12px; align-items: center; }
.copy-button:hover { background: #444; }
.terminal pre { font: 11px/1.8 var(--mono); padding: 18px; margin: 0; }
.terminal-result { border-top: 1px solid #555; padding: 15px 18px; margin-top: auto; }
.terminal-result .small-label { color: #bbb; }
.terminal-result p { font-size: 12px; margin: 8px 0 0; }
.build-footnote { font-size: 11px; color: var(--muted); margin-top: 22px; }
.toolkit-controls { display: flex; justify-content: space-between; flex-wrap: wrap; gap: 20px; align-items: center; margin: 4px 0 20px; }
.filter-list { display: flex; gap: 6px; flex-wrap: wrap; }
.filter { font-size: 11px; border: 1px solid transparent; padding: 7px 11px; background: none; }
.filter.active { border-color: #aaa; background: #e4e4e4; }
.filter:hover { background: #e9e9e9; }
.search-label { display: flex; align-items: center; border-bottom: 1px solid #aaa; gap: 8px; padding: 5px 0; }
.search-label input { font-size: 12px; width: 160px; background: none; border: 0; border-radius: 0; padding: 4px; }
.toolkit-table { border-top: 1px solid #aaa; }
.toolkit-table-head, .toolkit-row { display: grid; grid-template-columns: 1fr 1.25fr 90px; gap: 24px; }
.toolkit-table-head { font: 9px var(--mono); color: var(--muted); padding: 13px 0; border-bottom: 1px solid var(--line); }
.toolkit-table-head > span:last-child { text-align: right; }
.toolkit-row { align-items: center; padding: 20px 0; border-bottom: 1px solid var(--line); }
.toolkit-name { display: flex; gap: 17px; align-items: center; min-width: 0; }
.toolkit-number { font: 11px var(--mono); color: var(--muted); min-width: 22px; }
.toolkit-name strong { font-size: 14px; font-weight: 500; display: block; }
.toolkit-name small { font: 9px var(--mono); color: var(--muted); display: block; margin-top: 5px; }
.toolkit-row > p { font-size: 12px; margin: 0; color: var(--muted); }
.toolkit-row > a { font-size: 11px; text-align: right; white-space: nowrap; }
.toolkit-count { color: var(--muted); font-size: 10px; margin-top: 14px; }
#toolkit-empty { padding: 30px 0; color: var(--muted); font-size: 13px; }
.source-section { display: grid; grid-template-columns: 1fr 1fr; gap: 70px; padding-top: 38px; padding-bottom: 44px; border-top: 1px solid var(--line); }
.source-section h2 { font-size: 28px; }
.source-section > div > p:not(.eyebrow) { font-size: 13px; color: var(--muted); max-width: 390px; margin: 18px 0 22px; }
.source-notes > div { border-bottom: 1px solid var(--line); padding: 14px 0; }
.source-notes > div:first-child { padding-top: 0; }
.source-notes > div:last-child { border: 0; }
.source-notes .mono { font-size: 10px; }
.source-notes p { font-size: 12px; color: var(--muted); margin: 7px 0 0; }
.site-footer { border-top: 1px solid var(--line); padding-top: 22px; padding-bottom: 25px; display: flex; align-items: center; gap: 30px; font-size: 11px; color: var(--muted); }
.footer-brand { font-size: 17px; color: #222; display: flex; gap: 12px; }
.site-footer > div { display: flex; gap: 22px; margin-left: auto; align-items: center; }
.site-footer > div > span { font: 9px var(--mono); }
.toast { position: fixed; bottom: 24px; left: 50%; transform: translateX(-50%); background: #222; color: #fff; padding: 13px 23px; font-size: 12px; z-index: 20; max-width: calc(100% - 32px); text-align: center; }
.noscript { background: #222; color: #fff; padding: 15px 25px; position: fixed; bottom: 0; width: 100%; font-size: 12px; }
@media (max-width: 950px) {
  .shell, .site-header { padding-left: 26px; padding-right: 26px; }
  .hero { gap: 30px; }
  .site-header nav { gap: 16px; }
  .hero h1 { font-size: 43px; }
  .resource-grid { grid-template-columns: 180px minmax(0,1fr); gap: 18px; }
  .resource-sidebar { padding-right: 16px; }
  .role-panel { gap: 28px; }
}
@media (max-width: 720px) {
  .site-header { flex-wrap: wrap; gap: 14px; }
  .site-header nav { order: 3; width: 100%; margin: 0; justify-content: space-between; border-top: 1px solid var(--line); padding-top: 2px; }
  .nav-source { margin-left: auto; }
  .hero { grid-template-columns: 1fr; gap: 24px; padding-top: 32px; }
  .hero h1 { font-size: 42px; }
  .hero-summary { padding: 15px 18px; }
  .hero-summary dl { display: grid; grid-template-columns: repeat(2,minmax(0,1fr)); gap: 0 20px; }
  .hero-summary dl > div { display: block; }
  .hero-summary dd { margin-top: 4px; }
  .section { padding-top: 36px; padding-bottom: 36px; }
  .section-heading { display: block; }
  .section-heading > p { margin-top: 14px; }
  h2 { font-size: 28px; }
  .setup-top { align-items: flex-start; flex-direction: column; gap: 12px; }
  .setup-actions { width: 100%; }
  .setup-tabs button { padding: 13px 8px; font-size: 11px; gap: 6px; }
  .setup-tabs button span { font-size: 10px; }
  .setup-pane { padding: 17px; }
  .resource-grid { grid-template-columns: 1fr; }
  .resource-sidebar { border-right: 0; border-bottom: 1px solid var(--line); padding: 0 0 15px; }
  .resource-list { flex-direction: row; overflow-x: auto; margin-bottom: 10px; }
  .resource-button { min-width: 130px; max-width: 180px; flex-shrink: 0; }
  .resource-sidebar > p { display: none; }
  .resource-sidebar .button { width: auto; }
  .field-grid { gap: 13px; }
  .review-bottom { grid-template-columns: 1fr; }
  .file-list { flex-direction: row; overflow-x: auto; }
  .file-list button { white-space: nowrap; }
  .review-summary > div { padding: 12px; }
  .review-summary strong { font-size: 13px; }
  .setup-footer { padding: 13px 16px; }
  .other-workflows { gap: 12px 20px; }
  .other-workflows .small-label { width: 100%; }
  .walkthrough-grid, .inspector-grid, .role-panel, .source-section { grid-template-columns: 1fr; }
  .steps { flex-direction: row; overflow-x: auto; border-right: 0; border-bottom: 1px solid var(--line); padding: 10px; }
  .step { flex: 1; justify-content: center; padding: 10px; }
  .step > span:nth-child(2), .step > span:last-child { display: none; }
  .step.active .step-number:after { content: ' ↗'; }
  .inspect-input { border-right: 0; border-bottom: 1px solid var(--line); }
  .workbench-foot { display: block; }
  .workbench-foot p { margin-top: 7px; }
  .local-badge { display: none; }
  .role-panel { gap: 22px; }
  .source-section { gap: 28px; }
  .toolkit-table-head { display: none; }
  .toolkit-row { grid-template-columns: 1fr 80px; gap: 12px; }
  .toolkit-row > p { grid-column: 1/-1; grid-row: 2; padding-left: 39px; }
  .site-footer { flex-wrap: wrap; gap: 15px; }
  .site-footer > p { display: none; }
  .site-footer > div { gap: 16px; }
}
@media (max-width: 430px) {
  .shell, .site-header { padding-left: 16px; padding-right: 16px; }
  .hero h1 { font-size: 37px; letter-spacing: -1px; }
