.woo-file-list pre { max-height: 280px; overflow: auto; font-size: 11px; line-height: 1.65; padding: 12px 15px; margin: 0; border-bottom: 1px solid var(--line); }
.woo-connection-summary { margin-top: 18px; }
.woo-command { border: 1px solid var(--line); margin: 16px 0; }
.woo-command > div { display: flex; justify-content: space-between; align-items: center; gap: 14px; padding: 10px 14px; border-bottom: 1px solid var(--line); background: #f6f6f6; }
