}

.woo-route > details { padding: 12px 15px; }
.woo-route > details > summary { cursor: pointer; font-size: 12px; font-weight: 600; }
.woo-route > .text-button { margin: 8px 15px 14px; }
.woo-catalog-table-wrap { max-width: 100%; overflow-x: auto; margin-top: 12px; }
